/// Build the footer hint list for the current app state.
fn footer_hints(app: &App) -> Vec<Hint> {
    footer_hints_ctx(footer_ctx(app))
}

fn hint_width(h: &Hint) -> usize {
    disp_width(h.0) + 1 + disp_width(h.1)
}

/// Information-density tier for the footer, chosen from the terminal width.
/// Small screens get only the highest-frequency keys so the line never has to
/// cut a hint in half (and never silently loses its escape hatch).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum FooterTier {
    Mini,    // < 60 cols
    Compact, // 60..99
    Full,    // >= 100
}

fn footer_tier(width: usize) -> FooterTier {
    if width < 60 {
        FooterTier::Mini
    } else if width < 100 {
        FooterTier::Compact
    } else {
        FooterTier::Full
    }
}

/// Maximum number of leading hints a tier shows, or `None` for "show them all".
fn footer_tier_cap(tier: FooterTier) -> Option<usize> {
    match tier {
        FooterTier::Mini => Some(4),
        FooterTier::Compact => Some(6),
        FooterTier::Full => None,
    }
}

/// The pinned final hint. When the tier hid some keys the label invites a second
/// look (`? 更多`) rather than merely naming the help overlay.
fn footer_help_hint(more: bool) -> Hint {
    if more {
        ("?", t("更多"))
    } else {
        ("?", t("帮助"))
    }
}

/// Choose which leading hints to show in `width`. The width tier caps the count
/// (4 / 6 / all); within the cap hints are appended while they fit, so a single
/// hint is never split. Returns the chosen hints and whether any were hidden
/// (the pinned help hint then reads `? 更多`).
fn footer_select<'a>(hints: &'a [Hint], width: usize) -> (Vec<&'a Hint>, bool) {
    let (help, lead) = hints.split_last().expect("footer always has a hint");
    let cap = footer_tier_cap(footer_tier(width));
    // Reserve the pinned help hint plus the separators on either side of it.
    let mut budget = width.saturating_sub(hint_width(help) + 5);
    let mut chosen: Vec<&'a Hint> = Vec::new();
    let mut hidden = false;
    for (i, h) in lead.iter().enumerate() {
        if cap.is_some_and(|c| i >= c) {
            hidden = true;
            break;
        }
        let w = hint_width(h);
        if w + 3 <= budget {
            budget -= w + 3;
            chosen.push(h);
        } else {
            hidden = true;
            break;
        }
    }
    (chosen, hidden)
}

#[cfg(test)]
/// Display width of the rendered footer line for a chosen set, used by tests.
/// Mirrors exactly what [`render_footer`] draws: the chosen hints, the pinned
/// help hint (whose label depends on `more`), and one `" · "` per gap.
fn footer_line_width(chosen: &[&Hint], more: bool) -> usize {
    let help = footer_help_hint(more);
    let w: usize = chosen.iter().map(|h| hint_width(h)).sum::<usize>() + hint_width(&help);
    w + chosen.len() * 3
}

fn render_footer(f: &mut Frame, area: Rect, app: &App) {
    let hints = footer_hints(app);
    let (chosen, more) = footer_select(&hints, area.width as usize);
    let help = footer_help_hint(more);
    let mut spans: Vec<Span> = Vec::new();
    let sep = Span::styled(" · ", Style::default().fg(Color::DarkGray));
    let key_style = Style::default()
        .fg(Color::Cyan)
        .add_modifier(Modifier::BOLD);
    let desc_style = Style::default().fg(Color::DarkGray);
    for h in &chosen {
        if !spans.is_empty() {
            spans.push(sep.clone());
        }
        spans.push(Span::styled(h.0, key_style));
        spans.push(Span::styled(format!(" {}", h.1), desc_style));
    }
    if !spans.is_empty() {
        spans.push(sep);
    }
    spans.push(Span::styled(help.0, key_style));
    spans.push(Span::styled(format!(" {}", help.1), desc_style));
    f.render_widget(Paragraph::new(Line::from(spans)), area);
}

fn render_browse(f: &mut Frame, area: Rect, app: &mut App) {
    let mode = app.layout_mode;
    let has_cmd = app.backend_kind != Backend::Sql;
    let sidebar_collapsed = pane_eff_collapsed(app, PANE_SIDEBAR);
    let editor_collapsed = pane_eff_collapsed(app, PANE_EDITOR);
    let results_collapsed = pane_eff_collapsed(app, PANE_RESULTS);

    // Stacked layout when the terminal is narrow or the sidebar is collapsed:
    // the sidebar becomes a one-line strip above the editor / results column.
    if mode == LayoutMode::Narrow || sidebar_collapsed {
        let sidebar_h = if sidebar_collapsed { 1 } else { 7 };
        let v = Layout::vertical([Constraint::Length(sidebar_h), Constraint::Min(4)]).split(area);
        app.rects.sidebar = v[0];
        if sidebar_collapsed {
            render_sidebar_strip(f, v[0], app);
        } else {
            render_sidebar(f, v[0], app);
        }
        render_main_area(f, v[1], app, editor_collapsed, results_collapsed, has_cmd);
    } else {
        let sidebar_w = sidebar_width(app.term_w, mode, sidebar_tree_longest_name(app));
        let hz =
            Layout::horizontal([Constraint::Length(sidebar_w), Constraint::Min(20)]).split(area);
        app.rects.sidebar = hz[0];
        render_sidebar(f, hz[0], app);
        render_main_area(f, hz[1], app, editor_collapsed, results_collapsed, has_cmd);
    }
}

fn render_main_area(
    f: &mut Frame,
    area: Rect,
    app: &mut App,
    editor_collapsed: bool,
    results_collapsed: bool,
    has_cmd: bool,
) {
    let mode = app.layout_mode;
    let cmd_h = if has_cmd { 3 } else { 0 };
    let base_editor_h = if mode == LayoutMode::Narrow { 3 } else { 5 };
    // Narrow + Editor 焦点：同帧把编辑器 3→6 行（小屏 height<14 或放不下时不扩）
    let expand_editor = mode == LayoutMode::Narrow
        && app.focus == Focus::Editor
        && app.term_h >= 14
        && area.height as usize >= 6 + cmd_h as usize + 5;
    let editor_h = if editor_collapsed {
        1
    } else if expand_editor {
        6
    } else {
        base_editor_h
    };
    let results_c = if results_collapsed {
        Constraint::Length(1)
    } else {
        Constraint::Min(5)
    };
    let main_chunks = Layout::vertical([
        Constraint::Length(editor_h),
        Constraint::Length(cmd_h),
        results_c,
    ])
    .split(area);
    app.rects.editor = main_chunks[0];
    app.rects.cmd = if has_cmd {
        main_chunks[1]
    } else {
        Rect::default()
    };

    if editor_collapsed {
        render_editor_strip(f, main_chunks[0], app);
    } else {
        let focused = app.focus == Focus::Editor;
        // R54: a read-only connection says so right on the editor title, so the
        // write policy is visible next to the SQL being typed (not just on the
        // tree root).
        let ro = app.selected.as_ref().is_some_and(|c| c.read_only);
        let block = Block::default()
            .borders(Borders::ALL)
            .title(if ro { " SQL 🔒 " } else { " SQL " })
            .border_set(border::ROUNDED)
            .border_style(border_style(focused));
        app.editor.set_block(block);
        // Keep the click-to-place-caret mirror in step with the widget: the
        // bordered inner area is the viewport, and the widget re-derives its own
        // scroll origin from the previous one plus the cursor on every render.
        app.editor_vp.resize(
            main_chunks[0].width.saturating_sub(2),
            main_chunks[0].height.saturating_sub(2),
        );
        app.editor_vp.follow(app.editor.cursor());
        f.render_widget(&app.editor, main_chunks[0]);
        // R56: dim every statement except the caret's own, then mark the bracket
        // pair on top (so the accent survives the dim). R61: the find matches go
        // on last so their background wins over both.
        paint_statement_dim(f, main_chunks[0], app);
        paint_bracket_pair(f, main_chunks[0], app);
        paint_editor_find(f, main_chunks[0], app);
    }

    if has_cmd {
        let title = match app.backend_kind {
            Backend::Redis => format!(" redis[{}] ", app.redis_db),
            Backend::Mongo => format!(" mongo({}) ", app.current_db()),
            Backend::Sql => " cmd ".into(),
        };
        let cfocused = app.focus == Focus::CmdInput;
        let b = Block::default()
            .borders(Borders::ALL)
            .title(Span::styled(title, Style::default().fg(Color::Magenta)))
            .border_set(border::ROUNDED)
            .border_style(border_style(cfocused));
        app.cmd_input.set_block(b);
        f.render_widget(&app.cmd_input, main_chunks[1]);
    }

    let res_area = main_chunks[2];
    app.rects.results = res_area;
    if results_collapsed {
        render_results_strip(f, res_area, app);
    } else {
        render_results_pane(f, res_area, app);
    }
}

/// R56: dim the editor lines that belong to a statement other than the one the
/// caret is in, so a multi-statement buffer reads as one bright block amid the
/// rest. Purely presentational — no key, no state, no query — and it only
/// touches the foreground colour of a cell, so the textarea's own caret / line
/// highlight (background + modifiers) survives. A single-statement buffer is
/// left untouched; the span is resolved by [`active_statement_rows`].
fn paint_statement_dim(f: &mut Frame, area: Rect, app: &App) {
    let (row, col) = app.editor.cursor();
    let Some((active_lo, active_hi)) = active_statement_rows(app.editor.lines(), row, col) else {
        return;
    };
    // tui-textarea draws the text inside the `Borders::ALL` block dbxt sets on
    // it, so the glyph area is the block's inner rect.
    let inner = Rect {
        x: area.x.saturating_add(1),
        y: area.y.saturating_add(1),
        width: area.width.saturating_sub(2),
        height: area.height.saturating_sub(2),
    };
    if inner.width == 0 || inner.height == 0 {
        return;
    }
    let top_row = app.editor_vp.row as usize;
    for i in 0..inner.height as usize {
        let r = top_row + i;
        if r >= active_lo && r <= active_hi {
            continue;
        }
        let y = inner.y + i as u16;
        for x in inner.x..inner.x + inner.width {
            let cell = &mut f.buffer_mut()[(x, y)];
            cell.fg = Color::DarkGray;
        }
    }
}

/// R53: mark the editor caret's bracket and its match, straight in the frame
/// buffer after the textarea drew. Purely presentational — no key, no state, no
/// query — so it can never affect execution; the pair is resolved from the
/// caret's ±[`BRACKET_SCAN_LINES`] lines only. The glyph stays exactly where the
/// widget painted it; only the colour and modifiers are added. Underline alone
/// would not stand out (tui-textarea already underlines the caret's whole line),
/// so the pair gets the accent colour plus bold as well.
fn paint_bracket_pair(f: &mut Frame, area: Rect, app: &App) {
    let Some((a, b)) = editor_bracket_pair(app) else {
        return;
    };
    // tui-textarea draws the text inside the `Borders::ALL` block dbxt sets on
    // it, so the glyph area is the block's inner rect.
    let inner = Rect {
        x: area.x.saturating_add(1),
        y: area.y.saturating_add(1),
        width: area.width.saturating_sub(2),
        height: area.height.saturating_sub(2),
    };
    if inner.width == 0 || inner.height == 0 {
        return;
    }
    // The widget's own scroll origin for this frame, mirrored in `editor_vp`.
    let top_row = app.editor_vp.row as usize;
    let top_col = app.editor_vp.col as usize;
    let lines = app.editor.lines();
    for (row, col) in [a, b] {
        let Some(line) = lines.get(row) else {
            continue;
        };
        let dcol = editor_display_col(line, col);
        if row < top_row || row - top_row >= inner.height as usize {
            continue;
        }
        if dcol < top_col || dcol - top_col >= inner.width as usize {
            continue;
        }
        let x = inner.x + (dcol - top_col) as u16;
        let y = inner.y + (row - top_row) as u16;
        let cell = &mut f.buffer_mut()[(x, y)];
        cell.fg = Color::LightCyan;
        cell.modifier.insert(Modifier::UNDERLINED | Modifier::BOLD);
    }
}

/// R61: paint the editor find matches straight into the frame buffer, after the
/// textarea drew (and after the statement dim / bracket pair), so the highlight
/// sits on top. Purely presentational: no key, no state change, no query. Every
/// match shares one background; the match the caret jumped to (the one the `3/7`
/// count names) gets the accent colour, so the count and the screen agree.
/// Char columns are mapped through [`editor_display_col`], so tabs and wide CJK
/// characters highlight their real screen cells.
fn paint_editor_find(f: &mut Frame, area: Rect, app: &App) {
    if app.editor_find_needle.is_empty() {
        return;
    }
    let hits = editor_find_hits(app.editor.lines(), &app.editor_find_needle);
    if hits.is_empty() {
        return;
    }
    // tui-textarea draws the text inside the `Borders::ALL` block dbxt sets on
    // it, so the glyph area is the block's inner rect.
    let inner = Rect {
        x: area.x.saturating_add(1),
        y: area.y.saturating_add(1),
        width: area.width.saturating_sub(2),
        height: area.height.saturating_sub(2),
    };
    if inner.width == 0 || inner.height == 0 {
        return;
    }
    let top_row = app.editor_vp.row as usize;
    let top_col = app.editor_vp.col as usize;
    let lines = app.editor.lines();
    for (hi, hit) in hits.iter().enumerate() {
        let Some(line) = lines.get(hit.row) else {
            continue;
        };
        if hit.row < top_row || hit.row - top_row >= inner.height as usize {
            continue;
        }
        let current = app.editor_find_idx == Some(hi);
        let y = inner.y + (hit.row - top_row) as u16;
        for k in 0..hit.len {
            let dcol = editor_display_col(line, hit.col + k);
            if dcol < top_col || dcol - top_col >= inner.width as usize {
                continue;
            }
            // The next char's display column minus this one is the exact cell
            // span (a tab is 1..4 cells, a wide CJK glyph 2, a combining mark 0).
            let dnext = editor_display_col(line, hit.col + k + 1);
            let span = dnext.saturating_sub(dcol).max(1);
            let x0 = inner.x + (dcol - top_col) as u16;
            for dx in 0..span as u16 {
                if x0 + dx >= inner.x + inner.width {
                    break;
                }
                let cell = &mut f.buffer_mut()[(x0 + dx, y)];
                cell.fg = Color::Black;
                cell.bg = if current {
                    Color::LightGreen
                } else {
                    Color::Yellow
                };
                if current {
                    cell.modifier.insert(Modifier::BOLD);
                }
            }
        }
    }
}

/// One-line summary shown in place of the sidebar when it is collapsed.
fn render_sidebar_strip(f: &mut Frame, area: Rect, app: &mut App) {
    let focused = app.focus == Focus::Sidebar;
    let mut text = String::new();
    if let Some(c) = &app.selected {
        if app.backend_kind == Backend::Redis {
            text.push_str(&tf(
                "▸ {} · {} keys",
                &[&(truncate_disp(&c.name, 16)), &(app.redis_scan.keys.len())],
            ));
            text.push_str(&format!(" · db{}", app.redis_db));
            if let Some(v) = &app.redis_value {
                text.push_str(&format!(" · {}", fix_double_encoding(&v.key_display)));
            }
        } else {
            text.push_str(&tf(
                "▸ {} · {} 表",
                &[&(truncate_disp(&c.name, 16)), &(app.tables.len())],
            ));
            let db = app.current_db();
            if !db.is_empty() {
                let schema = if app.schema.is_empty() {
                    String::new()
                } else {
                    format!(".{}", fix_double_encoding(&app.schema))
                };
                text.push_str(&format!(" · {db}{schema}", db = fix_double_encoding(&db)));
            }
            if let Some(t) = app.selected_table() {
                text.push_str(&format!(" · {}", fix_double_encoding(&t.name)));
            }
        }
    } else {
        text.push_str(t("▸ 未连接"));
    }
    text.push_str(t(" · 点击/Ctrl-W 展开"));
    let style = if focused {
        Style::default()
            .fg(Color::Black)
            .bg(Color::Green)
            .add_modifier(Modifier::BOLD)
    } else {
        Style::default()
            .fg(Color::Green)
            .add_modifier(Modifier::BOLD)
    };
    f.render_widget(
        Paragraph::new(truncate_disp(&text, area.width as usize)).style(style),
        area,
    );
}

/// One-line summary shown in place of the SQL editor when it is collapsed.
fn render_editor_strip(f: &mut Frame, area: Rect, app: &mut App) {
    let focused = app.focus == Focus::Editor;
    let sql = app.editor_sql();
    let first = sql.lines().find(|l| !l.trim().is_empty()).unwrap_or("");
    let text = if first.is_empty() {
        t("SQL ▸ 空 · 点击/Tab 展开").to_string()
    } else {
        tf("SQL ▸ {} · 点击/Tab 展开", &[&(one_line(first))])
    };
    let style = if focused {
        Style::default()
            .fg(Color::Black)
            .bg(Color::Green)
            .add_modifier(Modifier::BOLD)
    } else {
        Style::default().fg(Color::Gray)
    };
    f.render_widget(
        Paragraph::new(truncate_disp(&text, area.width as usize)).style(style),
        area,
    );
}

/// One-line summary shown in place of the results pane when it is collapsed.
fn render_results_strip(f: &mut Frame, area: Rect, app: &mut App) {
    let n = result_row_count(app);
    let text = tf("结果 ▸ {} 行 · 点击/Ctrl-W 展开", &[&(n)]);
    f.render_widget(
        Paragraph::new(truncate_disp(&text, area.width as usize))
            .style(Style::default().fg(Color::Gray)),
        area,
    );
}

fn border_style(focused: bool) -> Style {
    if focused {
        Style::default().fg(Color::Green)
    } else {
        Style::default().fg(Color::DarkGray)
    }
}

fn render_results_pane(f: &mut Frame, area: Rect, app: &mut App) {
    if let Some(s) = app.script.clone() {
        if let Some(i) = s.drilled {
            let o = &s.outcomes[i];
            let title = tf(
                " {}语句 {} 结果 · {} · Esc 返回脚本 ",
                &[
                    &(search_marker(app)),
                    &(i + 1),
                    &(if o.grid.note.is_empty() {
                        "".to_string()
                    } else {
                        o.grid.note.clone()
                    }),
                ],
            );
            if let Some(grid) = active_grid(app) {
                render_grid(f, area, app, &grid, GridKind::Query, &title, false);
            }
        } else if app.show_stmt_timing {
            // R42 console feel: statement separators + a `12.3ms` prefix per
            // statement (Alt-O).
            render_script_stream(f, area, app, &s);
        } else {
            render_script_list(f, area, app, &s);
        }
        return;
    }
    if app.struct_view == StructView::Ddl {
        if let Some(ddl) = app.ddl.clone() {
            render_ddl(f, area, app, &ddl);
            return;
        }
    }
    // R48: a pinned grid keeps an up-and-down comparison visible above the live
    // pane. Only on SQL data grids, and only when there is room for both.
    let area = if app.backend_kind == Backend::Sql {
        match app.pinned_result.clone() {
            Some(pin) if area.height >= 8 && area.width >= 12 => {
                let ph = (area.height / 3)
                    .clamp(4, 7)
                    .min(area.height.saturating_sub(4));
                let top = Rect { height: ph, ..area };
                let bottom = Rect {
                    y: area.y + ph,
                    height: area.height - ph,
                    ..area
                };
                let title = format!(
                    " 📌 {} ",
                    truncate_disp(&pin.title, area.width.saturating_sub(6) as usize)
                );
                // The pinned render writes app's scroll/grid caches for its own
                // widths; restore the column offset so the live pane below keeps
                // its place (the live render recomputes everything else).
                let saved_offset = app.col_offset;
                let saved_focus = app.focus;
                app.focus = Focus::Sidebar;
                render_grid(f, top, app, &pin.grid, pin.kind, &title, false);
                app.col_offset = saved_offset;
                app.focus = saved_focus;
                bottom
            }
            _ => area,
        }
    } else {
        area
    };
    if app.grid.is_some() {
        let title = grid_title(app);
        // Move the grid out instead of deep-cloning it every frame: a 20k-row
        // result is ~12 ms of allocation per frame otherwise. `render_grid` only
        // borrows it, so it is put back right after.
        let grid = app.grid.take().expect("grid present");
        let kind = app.grid_kind;
        render_grid(f, area, app, &grid, kind, &title, true);
        app.grid = Some(grid);
        return;
    }
    if app.backend_kind != Backend::Sql && !app.cmd_output.is_empty() {
        render_console(f, area, app);
        return;
    }
    let hint = if app.selected.is_none() {
        if app.picker_open {
            ""
        } else {
            t("q 显示连接列表")
        }
    } else if app.backend_kind == Backend::Redis {
        if app.redis_scan.keys.is_empty() {
            t("无 key · Tab 到命令台 · / 匹配模式 · r 重扫")
        } else {
            t("↑↓ 选 key · Enter 查看值 · n 更多 · / 匹配模式\nTab 到命令台 · Ctrl-L 切换模式")
        }
    } else if app.tables.is_empty() {
        t("无表 · Tab 到 SQL 编辑器 · Ctrl-L 切 redis/mongo 命令行")
    } else {
        t("↑↓ 选表 · Enter 浏览数据 · r 表结构\nTab 到 SQL 编辑器 · Ctrl-L 切 redis/mongo 命令行")
    };
    f.render_widget(
        Paragraph::new(hint)
            .style(Style::default().fg(Color::DarkGray))
            .block(
                Block::default()
                    .borders(Borders::ALL)
                    .title(t(" 结果 "))
                    .border_set(border::ROUNDED)
                    .border_style(border_style(app.focus == Focus::Preview)),
            ),
        area,
    );
}

/// Leading marker for an active result search, so the indicator stays visible
/// even when a narrow pane clips the rest of the title.
fn search_marker(app: &App) -> String {
    let mut out = String::new();
    if !app.result_needle.trim().is_empty() {
        out.push_str(&tf(
            "🔍「{}」{} 命中 · ",
            &[&(app.result_needle), &(result_row_count(app))],
        ));
    }
    // R52 column filter: name the column and the live hit count so a filtered
    // grid is never mistaken for the whole result.
    if let Some((name, needle)) = app.col_filter_spec().filter(|(_, n)| !n.trim().is_empty()) {
        out.push_str(&tf(
            "▤{}「{}」{} 行 · ",
            &[
                &(fix_double_encoding(name)),
                &(needle),
                &(result_row_count(app)),
            ],
        ));
    }
    out
}

/// Compressed table-browser title for a narrow terminal: table name, page
/// number and the filter / search marks survive; everything else is dropped.
fn narrow_table_title(app: &App, ps: &PageState) -> String {
    let table = fix_double_encoding(&qualified_display(&ps.schema, &ps.table));
    let mut marks = String::new();
    if !app.result_needle.trim().is_empty() {
        marks.push('🔍');
    }
    if app
        .col_filter_spec()
        .is_some_and(|(_, n)| !n.trim().is_empty())
    {
        marks.push('▤');
    }
    if !ps.filter.trim().is_empty() {
        marks.push('⚑');
    }
    let marks = if marks.is_empty() {
        String::new()
    } else {
        format!(" {marks}")
    };
    tf(
        " {}.{}{} · p{} ",
        &[
            &fix_double_encoding(&app.current_db()),
            &table,
            &marks,
            &(ps.page + 1),
        ],
    )
}

fn grid_title(app: &App) -> String {
    // On a narrow terminal the title is clipped by the pane, so keep only the
    // three essentials — table name, page number, filter/search marks — and drop
    // the row range, note and next-page hint. `term_w == 0` (tests) is treated as
    // wide so the full title is exercised.
    let narrow = app.term_w > 0 && app.term_w < 56;
    match app.grid_kind {
        GridKind::TableData => {
            let Some(ps) = &app.page_state else {
                return t(" 结果 ").into();
            };
            if narrow {
                return narrow_table_title(app, ps);
            }
            let rows = app.grid.as_ref().map(|g| g.rows.len()).unwrap_or(0);
            let offset = ps.page * ps.page_size;
            let total = total_label(ps);
            let more = if ps.has_next {
                t(" · n 下一页")
            } else {
                ""
            };
            let table_label = fix_double_encoding(&qualified_display(&ps.schema, &ps.table));
            tf(
                " {}{}.{} · 第 {} 页 · {}–{} / {} · {}{}{} ",
                &[
                    &(search_marker(app)),
                    &(fix_double_encoding(&app.current_db())),
                    &(table_label),
                    &(ps.page + 1),
                    &(if rows == 0 { 0 } else { offset + 1 }),
                    &(offset + rows),
                    &(total),
                    &(app
                        .grid
                        .as_ref()
                        .map(|g| g.note.clone())
                        .unwrap_or_default()),
                    &(more),
                    &(page_state_extra(ps)),
                ],
            )
        }
        GridKind::Columns => {
            let table = app
                .selected_table()
                .map(|t| fix_double_encoding(&qualified_display(&app.schema, &t.name)))
                .unwrap_or_default();
            tf(
                " 表结构 · {} · {} · t 查看 DDL ",
                &[
                    &(table),
                    &(app
                        .grid
                        .as_ref()
                        .map(|g| g.note.clone())
                        .unwrap_or_default()),
                ],
            )
        }
        GridKind::Query => {
            let note = app
                .grid
                .as_ref()
                .map(|g| g.note.clone())
                .unwrap_or_default();
            if app.result_tabs.len() > 1 {
                let title = app
                    .result_tabs
                    .get(app.result_tab)
                    .map(|t| t.title.clone())
                    .unwrap_or_default();
                tf(
                    " {}结果 {}/{} · {} · {} · [ ] 切换 ",
                    &[
                        &(search_marker(app)),
                        &(app.result_tab + 1),
                        &(app.result_tabs.len()),
                        &(note),
                        &(truncate_disp(&title, 20)),
                    ],
                )
            } else {
                tf(" {}结果 · {} ", &[&(search_marker(app)), &(note)])
            }
        }
        GridKind::RedisValue => {
            let note = app
                .grid
                .as_ref()
                .map(|g| g.note.clone())
                .unwrap_or_default();
            match &app.redis_value {
                Some(v) => tf(
                    " {}Redis · {} · {} · TTL {} · {} · e 编辑 x TTL m 重命名 Del 删除 ",
                    &[
                        &(search_marker(app)),
                        &(fix_double_encoding(&v.key_display)),
                        &(v.redis_type),
                        &(redis_ttl_label(v.ttl)),
                        &(note),
                    ],
                ),
                None => tf(" {}Redis value · {} ", &[&(search_marker(app)), &(note)]),
            }
        }
        GridKind::MongoDocs => {
            let Some(ps) = &app.page_state else {
                return t(" 文档 ").into();
            };
            if narrow {
                return narrow_table_title(app, ps);
            }
            let rows = app.grid.as_ref().map(|g| g.rows.len()).unwrap_or(0);
            let offset = ps.page * ps.page_size;
            let total = ps
                .total
                .map(|t| tf("共 {} 个", &[&(t)]))
                .unwrap_or_else(|| t("总数未知").into());
            let more = if ps.has_next {
                t(" · n 下一页")
            } else {
                ""
            };
            let filt = if ps.filter.trim().is_empty() {
                String::new()
            } else {
                tf(" · 过滤 {}", &[&(truncate_disp(&ps.filter, 24))])
            };
            tf(
                " {}{}.{} · 第 {} 页 · {}–{} / {} · {}{}{} ",
                &[
                    &(search_marker(app)),
                    &(fix_double_encoding(&app.current_db())),
                    &(fix_double_encoding(&qualified_display(&ps.schema, &ps.table))),
                    &(ps.page + 1),
                    &(if rows == 0 { 0 } else { offset + 1 }),
                    &(offset + rows),
                    &(total),
                    &(app
                        .grid
                        .as_ref()
                        .map(|g| g.note.clone())
                        .unwrap_or_default()),
                    &(more),
                    &(filt),
                ],
            )
        }
    }
}

fn render_grid(
    f: &mut Frame,
    area: Rect,
    app: &mut App,
    grid: &Grid,
    kind: GridKind,
    title: &str,
    cache: bool,
) {
    let focused = app.focus == Focus::Preview;
    let block = Block::default()
        .borders(Borders::ALL)
        .title(title.to_string())
        .border_set(border::ROUNDED)
        .border_style(border_style(focused));

    if grid.columns.is_empty() {
        let body = if grid.note.is_empty() {
            "OK".to_string()
        } else {
            grid.note.clone()
        };
        f.render_widget(
            Paragraph::new(body)
                .style(Style::default().fg(Color::DarkGray))
                .block(block),
            area,
        );
        return;
    }

    let total_rows = grid.rows.len();
    let gutter = ((total_rows + 1).to_string().len()).max(2) as u16;

    // Fixed layout for the structure field list; windowed layout for data grids.
    if kind == GridKind::Columns {
        render_columns_grid(f, area, app, grid, block, gutter);
        return;
    }

    let inner_w = area.width.saturating_sub(2) as usize;
    let ncols = grid.columns.len();
    // Highlight cells that match the active result search (`/` in the results).
    let needle_lc = app.result_needle.trim().to_lowercase();
    let needle = if needle_lc.is_empty() {
        None
    } else {
        Some(needle_lc.as_str())
    };
    // Compact (mobile) mode shares the pane among all columns so a wide table can
    // fit without horizontal scrolling; otherwise each column keeps its natural
    // content width, capped per layout.
    let max_cell = grid_max_cell(app, ncols, inner_w, gutter);
    app.grid_max_cell = max_cell;
    // Column widths are content-sized, so building them scans every cell. Cache
    // them per displayed grid (and width cap) so scrolling 20k rows is a lookup,
    // not a rescan. The drilled-script grid is rebuilt per frame, so it skips
    // the cache.
    let mut widths: Vec<usize> = if cache {
        app.column_widths(grid, max_cell)
    } else {
        natural_widths(grid, max_cell)
    };
    // R55: a session column-width override wins over the natural width, so a
    // manual `<` / `>` adjustment survives page turns and re-queries.
    apply_col_width_overrides(app, grid, &mut widths);
    let frozen =
        effective_frozen_widths(app.freeze_first, ncols, &widths, gutter as usize, inner_w);
    let left_w: usize = gutter as usize
        + if frozen > 0 {
            frozen + widths[..frozen].iter().sum::<usize>()
        } else {
            0
        };
    const GAP: usize = 1;
    let avail = inner_w.saturating_sub(left_w + GAP).max(MIN_CELL_WIDTH);
    app.grid_avail = avail;
    let (off, visible) =
        window_for_cursor_widths(&widths, app.col_cursor, app.col_offset, avail, frozen);
    app.col_offset = off;
    app.vis_cols = visible;
    app.grid_gutter = gutter;
    app.grid_frozen = frozen;
    app.grid_widths = widths.clone();

    // Sort / filter marks only make sense for a browsed table.
    let (sort_keys, filter_text) = if kind == GridKind::TableData {
        match &app.page_state {
            Some(ps) => (parse_order_by(ps.order_by.as_deref()), ps.filter.clone()),
            None => (Vec::new(), String::new()),
        }
    } else {
        (Vec::new(), String::new())
    };
    let sort_of = |name: &str| {
        sort_keys
            .iter()
            .position(|(c, _)| c == name)
            .map(|i| (sort_keys[i].1, i + 1))
    };
    let filt_of = |name: &str| !filter_text.is_empty() && filter_mentions(&filter_text, name);

    let h = (area.height as usize).saturating_sub(3).max(1);
    let nrows = grid.rows.len();
    let start = app
        .sel
        .saturating_sub(h / 2)
        .min(nrows.saturating_sub(h.min(nrows)));
    let sel = app.sel;
    let cc = app.col_cursor;
    // R57: the row-select block, if any, drawn as full-row reverse video.
    let sel_range = app.row_sel_anchor.map(|a| (a.min(sel), a.max(sel)));

    let inner = block.inner(area);
    f.render_widget(block, area);

    // ── pinned block: row-number gutter + optionally the first data column ──
    let mut left_widths: Vec<usize> = vec![gutter as usize];
    left_widths.extend(widths[..frozen].iter().copied());
    let mut lheader: Vec<Cell> = vec![gutter_header_cell()];
    for (ci, w) in widths.iter().enumerate().take(frozen) {
        let name = &grid.columns[ci];
        lheader.push(col_header_cell(
            &fix_double_encoding(name),
            *w,
            ci == cc,
            sort_of(name),
            filt_of(name),
        ));
    }
    let mut lrows: Vec<Row> = Vec::new();
    for (i, row) in grid.rows.iter().enumerate().skip(start).take(h) {
        let mut cells: Vec<Cell> = vec![gutter_cell(i, i == sel)];
        for (ci, w) in widths.iter().enumerate().take(frozen) {
            cells.push(match row.get(ci) {
                Some(v) => cell_widget_hl(v, *w, i == sel && ci == cc, needle),
                None => Cell::from(""),
            });
        }
        let mut r = Row::new(cells);
        if sel_range.is_some_and(|(lo, hi)| i >= lo && i <= hi) {
            r = r.style(row_select_style());
        } else if i == sel {
            r = r.style(highlight_style());
        }
        lrows.push(r);
    }
    let left_area = Rect {
        x: inner.x,
        y: inner.y,
        width: (left_w.min(inner.width as usize)) as u16,
        height: inner.height,
    };
    let ltable = Table::new(
        lrows,
        left_widths
            .iter()
            .map(|w| Constraint::Length(*w as u16))
            .collect::<Vec<_>>(),
    )
    .header(Row::new(lheader))
    .column_spacing(1);
    f.render_widget(ltable, left_area);

    // ── scrollable window ──
    if visible > 0 && (inner.width as usize) > left_w + GAP {
        let right_x = inner.x + (left_w + GAP) as u16;
        let right_w = (inner.x + inner.width).saturating_sub(right_x);
        if right_w > 0 {
            let right_area = Rect {
                x: right_x,
                y: inner.y,
                width: right_w,
                height: inner.height,
            };
            let mut rheader: Vec<Cell> = Vec::new();
            for (ci, w) in widths.iter().enumerate().skip(off).take(visible) {
                let name = &grid.columns[ci];
                rheader.push(col_header_cell(
                    &fix_double_encoding(name),
                    *w,
                    ci == cc,
                    sort_of(name),
                    filt_of(name),
                ));
            }
            let mut rrows: Vec<Row> = Vec::new();
            for (i, row) in grid.rows.iter().enumerate().skip(start).take(h) {
                let mut cells: Vec<Cell> = Vec::new();
                for (ci, w) in widths.iter().enumerate().skip(off).take(visible) {
                    cells.push(match row.get(ci) {
                        Some(v) => cell_widget_hl(v, *w, i == sel && ci == cc, needle),
                        None => Cell::from(""),
                    });
                }
                let mut r = Row::new(cells);
                if sel_range.is_some_and(|(lo, hi)| i >= lo && i <= hi) {
                    r = r.style(row_select_style());
                } else if i == sel {
                    r = r.style(highlight_style());
                }
                rrows.push(r);
            }
            let rtable = Table::new(
                rrows,
                (off..off + visible)
                    .map(|ci| Constraint::Length(widths[ci] as u16))
                    .collect::<Vec<_>>(),
            )
            .header(Row::new(rheader))
            .column_spacing(1);
            f.render_widget(rtable, right_area);
        }
    }

    // ── horizontal scroll progress bar (drawn on the bottom border) ──
    app.rects.hbar_visible = false;
    app.rects.hbar_prev = Rect::default();
    app.rects.hbar_next = Rect::default();
    let scrollable_total = ncols.saturating_sub(frozen);
    // R47b: auto-hide. The bar only appears for a moment after a horizontal
    // scroll (`poke_hbar`), so the bottom border is not a permanent thick band.
    // The `列 k/N` readout in the status line still names the window at rest.
    let hbar_shown = hbar_should_show(app.hbar_until, Instant::now());
    // The bar sits on the bottom border, so a zero-height results pane (a tiny
    // terminal squeezes the pane to nothing) has no row to draw it on and
    // `area.height - 1` would underflow.
    if hbar_shown && visible > 0 && scrollable_total > visible && inner_w >= 16 && area.height > 0 {
        let win_start = off.saturating_sub(frozen);
        let pin = match frozen {
            0 => String::new(),
            1 => "1|".to_string(),
            f => format!("1-{f}|"),
        };
        let label = tf(
            "列 {}{}-{}/{}",
            &[&(pin), &(off + 1), &(off + visible), &(ncols)],
        );
        // One cell at each end is a tap target for panning a whole window — the
        // touch-friendly control for phones whose terminal sends no h-wheel.
        let track = inner_w - 2;
        let label_w = disp_width(&label);
        let bar_len = if track > label_w + 6 {
            track - label_w - 1
        } else {
            track
        };
        let (ts, tl) = scrollbar_geom(scrollable_total, win_start, visible, bar_len);
        let tl = tl.max(1).min(bar_len);
        let mut spans: Vec<Span> = Vec::new();
        spans.push(Span::styled("◀", Style::default().fg(Color::LightGreen)));
        // R47b: a dashed mid-line track plus a heavy mid-line thumb. Both sit on
        // the same thin line, so the bar reads as one hairline with a bright
        // segment instead of the old `▁`/`▄` band that stood half a cell tall.
        if ts > 0 {
            spans.push(Span::styled(
                "┄".repeat(ts),
                Style::default().fg(Color::DarkGray),
            ));
        }
        spans.push(Span::styled(
            "━".repeat(tl),
            Style::default().fg(Color::LightGreen),
        ));
        let after = bar_len.saturating_sub(ts + tl);
        if after > 0 {
            spans.push(Span::styled(
                "┄".repeat(after),
                Style::default().fg(Color::DarkGray),
            ));
        }
        if bar_len < track {
            let pad = track - bar_len - label_w;
            if pad > 0 {
                spans.push(Span::raw(" ".repeat(pad)));
            }
            spans.push(Span::styled(label, Style::default().fg(Color::Gray)));
        }
        spans.push(Span::styled("▶", Style::default().fg(Color::LightGreen)));
        let bar_area = Rect {
            x: inner.x,
            y: area.y + area.height - 1,
            width: inner_w as u16,
            height: 1,
        };
        f.render_widget(Paragraph::new(Line::from(spans)), bar_area);
        app.rects.hbar_prev = Rect {
            x: inner.x,
            y: bar_area.y,
            width: 1,
            height: 1,
        };
        app.rects.hbar_next = Rect {
            x: inner.x + inner_w as u16 - 1,
            y: bar_area.y,
            width: 1,
            height: 1,
        };
        app.rects.hbar = Rect {
            x: inner.x + 1,
            y: bar_area.y,
            width: bar_len as u16,
            height: 1,
        };
        app.rects.hbar_visible = bar_len > 0;
    }

    // ── vertical position indicator (drawn on the right border) ──
    let track_h = inner.height as usize;
    if track_h >= 3 {
        let win = h.min(nrows.saturating_sub(start)).max(1);
        let (v_total, v_start) = match (&app.page_state, kind) {
            (Some(ps), GridKind::TableData) => match ps.total {
                Some(t) if !ps.total_lower_bound && (t as usize) > win => {
                    (t as usize, ps.page * ps.page_size + start)
                }
                _ => (nrows, start),
            },
            _ => (nrows, start),
        };
        if v_total > win {
            let lines = vbar_lines(v_total, v_start, win, track_h);
            let v_area = Rect {
                x: area.x + area.width - 1,
                y: inner.y,
                width: 1,
                height: inner.height,
            };
            f.render_widget(Paragraph::new(lines), v_area);
        }
    }
}

/// Thumb geometry for a scrollbar track: `(thumb_start, thumb_len)` within
/// `track` cells for a window of `win_len` at `win_start` out of `total` items.
fn scrollbar_geom(total: usize, win_start: usize, win_len: usize, track: usize) -> (usize, usize) {
    if total == 0 || track == 0 {
        return (0, 0);
    }
    let win_len = win_len.clamp(1, total);
    if win_len >= total {
        return (0, track);
    }
    let thumb_len = ((win_len * track) / total).max(1).min(track);
    let max_start = total - win_len;
    let travel = track - thumb_len;
    let start = (win_start.min(max_start) * travel)
        .checked_div(max_start)
        .unwrap_or(0);
    (start.min(travel), thumb_len)
}

fn vbar_lines(total: usize, start: usize, win: usize, height: usize) -> Vec<Line<'static>> {
    let (ts, tl) = scrollbar_geom(total, start, win, height);
    let tl = tl.max(1).min(height);
    (0..height)
        .map(|i| {
            if i >= ts && i < ts + tl {
                // Half-width block: a thin vertical thumb on the right border.
                Line::from(Span::styled("▐", Style::default().fg(Color::LightGreen)))
            } else {
                Line::from(Span::styled("│", Style::default().fg(Color::DarkGray)))
            }
        })
        .collect()
}

/// True when `col` appears as a whole identifier inside the filter expression
/// (quote characters are ignored).
fn filter_mentions(filter: &str, col: &str) -> bool {
    if filter.trim().is_empty() || col.is_empty() {
        return false;
    }
    let cleaned: String = filter
        .chars()
        .filter(|c| !matches!(c, '`' | '"' | '[' | ']'))
        .collect();
    let hay = cleaned.to_ascii_lowercase();
    let needle = col.to_ascii_lowercase();
    let (hb, nb) = (hay.as_bytes(), needle.as_bytes());
    let (n, m) = (hb.len(), nb.len());
    if m == 0 || m > n {
        return false;
    }
    let ident = |b: u8| b.is_ascii_alphanumeric() || b == b'_';
    let mut i = 0;
    while i + m <= n {
        if &hb[i..i + m] == nb {
            let before_ok = i == 0 || !ident(hb[i - 1]);
            let after_ok = i + m == n || !ident(hb[i + m]);
            if before_ok && after_ok {
                return true;
            }
        }
        i += 1;
    }
    false
}

/// Table-structure field list: fixed percentage widths, but still shows the cell
/// cursor and focused-cell highlight for consistency with data grids.
fn render_columns_grid(
    f: &mut Frame,
    area: Rect,
    app: &mut App,
    grid: &Grid,
    block: Block,
    gutter: u16,
) {
    let widths = [
        Constraint::Length(gutter),
        Constraint::Percentage(22),
        Constraint::Percentage(20),
        Constraint::Length(5),
        Constraint::Length(5),
        Constraint::Percentage(22),
        Constraint::Percentage(26),
    ];
    let cc = app.col_cursor;
    let mut header = vec![gutter_header_cell()];
    header.extend(grid.columns.iter().enumerate().map(|(ci, c)| {
        let shown = fix_double_encoding(c);
        col_header_cell(&shown, disp_width(&shown), ci == cc, None, false)
    }));
    let rows: Vec<Row> = grid
        .rows
        .iter()
        .enumerate()
        .map(|(i, row)| {
            let mut cells = vec![gutter_cell(i, i == app.sel)];
            cells.extend(
                row.iter()
                    .enumerate()
                    .map(|(ci, v)| cell_widget_hl(v, 40, i == app.sel && ci == cc, None)),
            );
            let mut r = Row::new(cells);
            if i == app.sel {
                r = r.style(highlight_style());
            }
            r
        })
        .collect();
    let table = Table::new(rows, widths)
        .header(Row::new(header))
        .column_spacing(1)
        .block(block);
    f.render_widget(table, area);
}

fn gutter_header_cell() -> Cell<'static> {
    Cell::from(Span::styled("#", Style::default().fg(Color::DarkGray)))
}

fn gutter_cell(i: usize, selected: bool) -> Cell<'static> {
    let style = if selected {
        Style::default()
            .fg(Color::Black)
            .bg(Color::LightGreen)
            .add_modifier(Modifier::BOLD)
    } else {
        Style::default().fg(Color::DarkGray)
    };
    Cell::from(Span::styled(format!("{}", i + 1), style))
}

fn col_header_cell(
    name: &str,
    w: usize,
    current: bool,
    sort: Option<(bool, usize)>,
    filtered: bool,
) -> Cell<'static> {
    let mut suffix = String::new();
    if let Some((desc, rank)) = sort {
        suffix.push(' ');
        suffix.push(if desc { '▼' } else { '▲' });
        if rank > 1 {
            suffix.push_str(&rank.to_string());
        }
    }
    if filtered {
        suffix.push_str(" ⚑");
    }
    let sw = disp_width(&suffix);
    let text = if w > sw {
        format!("{}{}", truncate_disp(name, w - sw), suffix)
    } else {
        truncate_disp(suffix.trim_start(), w)
    };
    let style = if current {
        Style::default()
            .fg(Color::Black)
            .bg(Color::Cyan)
            .add_modifier(Modifier::BOLD)
    } else if sort.is_some() {
        Style::default()
            .fg(Color::Yellow)
            .add_modifier(Modifier::BOLD)
    } else if filtered {
        Style::default()
            .fg(Color::LightMagenta)
            .add_modifier(Modifier::BOLD)
    } else {
        Style::default()
            .fg(Color::Cyan)
            .add_modifier(Modifier::BOLD)
    };
    Cell::from(Span::styled(text, style))
}

fn highlight_style() -> Style {
    Style::default()
        .bg(Color::Rgb(38, 48, 38))
        .add_modifier(Modifier::BOLD)
}

/// R57: a row inside the rows-select block — full-row reverse video so a
/// multi-row selection reads as one solid band, clearly distinct from the
/// single cursor row's dark highlight above.
fn row_select_style() -> Style {
    Style::default().add_modifier(Modifier::REVERSED | Modifier::BOLD)
}

fn focused_cell_style() -> Style {
    Style::default()
        .fg(Color::Black)
        .bg(Color::LightCyan)
        .add_modifier(Modifier::BOLD)
}

/// Italic is a nicety, not a requirement: some terminals ignore it, some render
/// it as reverse video. The grey foreground alone still separates a real NULL
/// from ordinary text, so an unsupported italic degrades to grey-only. Set
/// `DBXT_NO_ITALIC=1` to force that fallback (or when the font's italic is hard
/// to read on a light theme).
fn italic_supported() -> bool {
    match std::env::var("DBXT_NO_ITALIC") {
        Ok(v) => {
            let v = v.trim();
            !(v == "1" || v.eq_ignore_ascii_case("true") || v.eq_ignore_ascii_case("yes"))
        }
        Err(_) => true,
    }
}

/// The style that marks a real SQL NULL: grey, italic when the terminal can.
fn null_style() -> Style {
    let mut style = Style::default().fg(Color::DarkGray);
    if italic_supported() {
        style = style.add_modifier(Modifier::ITALIC);
    }
    style
}

/// The style for an empty string — grey, never italic, and always drawn as
/// `''` so it can never be mistaken for NULL.
fn empty_string_style() -> Style {
    Style::default().fg(Color::DarkGray)
}

/// Text and style a value should be drawn with, shared by the grid, the cell /
/// row modals and the edit dialog so every surface tells the same story:
/// `NULL` = grey italic, `''` = grey, anything else = plain. A literal string
/// `"NULL"` stays plain, which is exactly how it stays distinct from the real
/// thing.
fn value_display(v: &Val) -> (String, Style) {
    match v {
        Val::Null => ("NULL".to_string(), null_style()),
        Val::Text(s) if s.is_empty() => ("''".to_string(), empty_string_style()),
        Val::Text(s) => (s.clone(), Style::default()),
    }
}

/// Style for a cell whose value matches the active result search.
fn search_hit_style() -> Style {
    Style::default()
        .fg(Color::Black)
        .bg(Color::Yellow)
        .add_modifier(Modifier::BOLD)
}

/// R58: longest value shown inline in a grid cell. A longer value collapses to
/// its first 38 display columns plus `…`, signalling that `v` (the R53 cell
/// popup) holds the full text. Kept as a constant so the width pass and the
/// render pass agree.
const CELL_TEXT_MAX: usize = 40;

/// R58: inline representation of a cell value. Values wider than
/// [`CELL_TEXT_MAX`] collapse to `first 38…`; everything else is returned as-is
/// (the caller still clamps to the column width).
fn abbreviate_cell_text(text: &str) -> String {
    if disp_width(text) > CELL_TEXT_MAX {
        truncate_disp(text, CELL_TEXT_MAX - 1)
    } else {
        text.to_string()
    }
}

/// R58: a cell value's contribution to its column width, capped at the inline
/// abbreviation so a long value no longer stretches its column past what is
/// actually drawn.
fn cell_text_width(v: &Val) -> usize {
    let w = disp_width(v.text());
    if w > CELL_TEXT_MAX {
        CELL_TEXT_MAX - 1
    } else {
        w
    }
}

/// Render one cell, optionally marking it as the focused cell or highlighting a
/// search hit.
fn cell_widget_hl(v: &Val, w: usize, focused: bool, needle: Option<&str>) -> Cell<'static> {
    if focused {
        let (text, _) = value_display(v);
        return Cell::from(Span::styled(
            truncate_disp(&abbreviate_cell_text(&text), w),
            focused_cell_style(),
        ));
    }
    let hit = needle.is_some_and(|n| {
        let s = match v {
            Val::Null => "null",
            Val::Text(s) => s.as_str(),
        };
        !n.is_empty() && s.to_lowercase().contains(n)
    });
    if hit {
        let (text, _) = value_display(v);
        return Cell::from(Span::styled(
            truncate_disp(&abbreviate_cell_text(&text), w),
            search_hit_style(),
        ));
    }
    match v {
        Val::Null => Cell::from(Span::styled("NULL", null_style())),
        Val::Text(s) if s.is_empty() => Cell::from(Span::styled("''", empty_string_style())),
        Val::Text(s) => Cell::from(Span::raw(truncate_disp(&abbreviate_cell_text(s), w))),
    }
}

fn render_script_list(f: &mut Frame, area: Rect, app: &mut App, script: &ScriptView) {
    let focused = app.focus == Focus::Preview;
    let errors = script.outcomes.iter().filter(|o| o.error.is_some()).count();
    let affected: u64 = script.outcomes.iter().map(|o| o.affected).sum();
    let title = tf(
        " 脚本 · {} 条语句 · 影响 {} 行 · {} 错误 · Enter 查看结果 ",
        &[&(script.outcomes.len()), &(affected), &(errors)],
    );
    let widths = [
        Constraint::Length(4),
        Constraint::Min(20),
        Constraint::Length(18),
        Constraint::Length(9),
    ];
    let rows: Vec<Row> = script
        .outcomes
        .iter()
        .enumerate()
        .map(|(i, o)| {
            let status = match &o.error {
                Some(e) => format!("✗ {}", truncate_disp(&one_line(e), 16)),
                None if !o.grid.columns.is_empty() => tf("{} 行", &[&(o.grid.rows.len())]),
                None => tf("影响 {} 行", &[&(o.affected)]),
            };
            let style = if o.error.is_some() {
                Style::default().fg(Color::Red)
            } else {
                Style::default()
            };
            let mut r = Row::new(vec![
                Cell::from(Span::styled(
                    format!("{}", i + 1),
                    Style::default().fg(Color::DarkGray),
                )),
                Cell::from(Span::raw(truncate_disp(&one_line(&o.sql), 80))),
                Cell::from(Span::styled(status, style)),
                Cell::from(Span::styled(
                    format!("{}ms", o.ms),
                    Style::default().fg(Color::DarkGray),
                )),
            ]);
            if i == script.sel {
                r = r.style(highlight_style());
            }
            r
        })
        .collect();
    let table = Table::new(rows, widths)
        .header(
            Row::new(vec!["#", t("语句"), t("结果"), t("耗时")]).style(
                Style::default()
                    .fg(Color::Cyan)
                    .add_modifier(Modifier::BOLD),
            ),
        )
        .column_spacing(1)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .title(title)
                .border_set(border::ROUNDED)
                .border_style(border_style(focused)),
        );
    f.render_widget(table, area);
}

/// Compact elapsed-time label for the script console: `12ms`, `1.23s`, `2.0m`.
fn format_elapsed_ms(ms: u128) -> String {
    if ms < 1_000 {
        format!("{ms}ms")
    } else if ms < 60_000 {
        format!("{:.2}s", ms as f64 / 1000.0)
    } else {
        format!("{:.1}m", ms as f64 / 60_000.0)
    }
}

/// R42 console-style script output: a separator line per statement carrying the
/// statement number and elapsed time, then the statement and its result. Shown
/// only when `show_stmt_timing` is on (`Alt-O`); the plain table is the default.
fn render_script_stream(f: &mut Frame, area: Rect, app: &mut App, script: &ScriptView) {
    let focused = app.focus == Focus::Preview;
    let errors = script.outcomes.iter().filter(|o| o.error.is_some()).count();
    let affected: u64 = script.outcomes.iter().map(|o| o.affected).sum();
    let title = tf(
        " 脚本输出 · {} 条 · 影响 {} 行 · {} 错误 · Alt-O 关分隔 ",
        &[&(script.outcomes.len()), &(affected), &(errors)],
    );
    let inner_w = area.width.saturating_sub(2).max(1) as usize;
    let inner_h = area.height.saturating_sub(2).max(1) as usize;
    // Three lines per statement: separator, statement, result.
    let mut lines: Vec<Line> = Vec::with_capacity(script.outcomes.len() * 3);
    for (i, o) in script.outcomes.iter().enumerate() {
        let head = format!("── #{} · {} ", i + 1, format_elapsed_ms(o.ms));
        let pad = inner_w.saturating_sub(disp_width(&head));
        let sep_style = Style::default().fg(Color::DarkGray);
        lines.push(Line::from(Span::styled(
            format!("{head}{}", "─".repeat(pad)),
            if i == script.sel {
                Style::default()
                    .fg(Color::Cyan)
                    .add_modifier(Modifier::BOLD)
            } else {
                sep_style
            },
        )));
        let sql_style = if i == script.sel {
            highlight_style()
        } else {
            Style::default()
        };
        lines.push(Line::from(Span::styled(
            truncate_disp(&one_line(&o.sql), inner_w),
            sql_style,
        )));
        let (status, status_style) = match &o.error {
            Some(e) => (
                format!(
                    "  ✗ {}",
                    truncate_disp(&one_line(e), inner_w.saturating_sub(4))
                ),
                Style::default().fg(Color::Red),
            ),
            None if !o.grid.columns.is_empty() => (
                format!("  ✓ {}", tf("{} 行", &[&o.grid.rows.len()])),
                Style::default().fg(Color::Green),
            ),
            None => (
                format!("  ✓ {}", tf("影响 {} 行", &[&o.affected])),
                Style::default().fg(Color::Green),
            ),
        };
        lines.push(Line::from(Span::styled(status, status_style)));
    }
    // Keep the selected statement visible: 3 lines per entry.
    let sel_line = script.sel * 3;
    let scroll = sel_line.saturating_sub(inner_h.saturating_sub(3)) as u16;
    f.render_widget(
        Paragraph::new(lines).scroll((scroll, 0)).block(
            Block::default()
                .borders(Borders::ALL)
                .title(title)
                .border_set(border::ROUNDED)
                .border_style(border_style(focused)),
        ),
        area,
    );
}

fn render_ddl(f: &mut Frame, area: Rect, app: &mut App, ddl: &str) {
    let focused = app.focus == Focus::Preview;
    let inner_w = area.width.saturating_sub(2).max(1) as usize;
    let inner_h = area.height.saturating_sub(2) as usize;
    let lines: Vec<String> = wrap_text(ddl, inner_w);
    let total = lines.len();
    let max_scroll = total.saturating_sub(inner_h) as u16;
    if app.ddl_scroll > max_scroll {
        app.ddl_scroll = max_scroll;
    }
    let table = app
        .selected_table()
        .map(|t| t.name.clone())
        .unwrap_or_default();
    let body: Vec<Line> = lines
        .iter()
        .map(|l| {
            let trimmed = l.trim_start();
            let indent = l.len() - trimmed.len();
            let style = if trimmed.starts_with("--") {
                Style::default().fg(Color::DarkGray)
            } else if is_ddl_keyword_line(trimmed) {
                Style::default().fg(Color::Cyan)
            } else {
                Style::default()
            };
            Line::from(vec![
                Span::raw(" ".repeat(indent)),
                Span::styled(trimmed.to_string(), style),
            ])
        })
        .collect();
    let title = tf(
        " 表结构 (DDL) · {} · {}/{} 行 · t 返回字段 ",
        &[
            &(fix_double_encoding(&table)),
            &((app.ddl_scroll as usize + inner_h).min(total)),
            &(total),
        ],
    );
    f.render_widget(
        Paragraph::new(body).scroll((app.ddl_scroll, 0)).block(
            Block::default()
                .borders(Borders::ALL)
                .title(title)
                .border_set(border::ROUNDED)
                .border_style(border_style(focused)),
        ),
        area,
    );
}

fn is_ddl_keyword_line(s: &str) -> bool {
    let up = s.to_ascii_uppercase();
    up.starts_with("CREATE ")
        || up.starts_with("PRIMARY KEY")
        || up.starts_with("UNIQUE KEY")
        || up.starts_with("KEY ")
        || up.starts_with("CONSTRAINT")
        || up.starts_with("FOREIGN KEY")
        || up.starts_with(")")
        || up.starts_with("ENGINE")
        || up.starts_with("DEFAULT CHARSET")
}

fn render_console(f: &mut Frame, area: Rect, app: &App) {
    // Console log: keep the newest output visible by scrolling to the bottom.
    let inner_w = area.width.saturating_sub(2).max(1) as usize;
    let inner_h = area.height.saturating_sub(2) as usize;
    let lines: Vec<Line> = app
        .cmd_output
        .iter()
        .flat_map(|entry| entry.lines().map(Line::raw))
        .collect();
    let rows: usize = lines
        .iter()
        .map(|l| {
            let w = l.width();
            if w == 0 {
                1
            } else {
                w.div_ceil(inner_w)
            }
        })
        .sum();
    let scroll_y = rows.saturating_sub(inner_h).min(u16::MAX as usize) as u16;
    f.render_widget(
        Paragraph::new(lines)
            .wrap(Wrap { trim: false })
            .scroll((scroll_y, 0))
            .block(
                Block::default()
                    .borders(Borders::ALL)
                    .title(t(" 输出 "))
                    .border_set(border::ROUNDED)
                    .border_style(border_style(app.focus == Focus::Preview)),
            ),
        area,
    );
}

fn render_sidebar(f: &mut Frame, area: Rect, app: &mut App) {
    let focused = app.focus == Focus::Sidebar;

    let Some(c) = app.selected.clone() else {
        // no connection selected: sidebar is just a placeholder (picker overlay does the job)
        let hint = if app.picker_open {
            ""
        } else {
            t("q 显示\n连接列表")
        };
        f.render_widget(
            Paragraph::new(hint)
                .style(Style::default().fg(Color::DarkGray))
                .block(
                    Block::default()
                        .borders(Borders::ALL)
                        .title(t(" 连接 "))
                        .border_set(border::ROUNDED)
                        .border_style(border_style(focused)),
                ),
            area,
        );
        return;
    };

    // Redis connections browse keys, not databases/tables: keep the flat key
    // browser (the tree only makes sense for SQL / Mongo).
    if app.backend_kind == Backend::Redis {
        let conn_color = connection_color(&c);
        let mut lines: Vec<Line> = Vec::new();
        // R47b: the same status dot the SQL/Mongo tree draws — Redis shares the
        // LocalBackend pool, so `remove_connection_pools` disconnects it too.
        let status = conn_status_for(app, &c.id);
        let dot_style = match status {
            ConnStatus::Active => Style::default().fg(conn_color),
            ConnStatus::Connecting => Style::default().fg(conn_color).add_modifier(Modifier::BOLD),
            ConnStatus::Idle => Style::default().fg(conn_color).add_modifier(Modifier::DIM),
        };
        let name_style = match status {
            ConnStatus::Active => Style::default().fg(conn_color).add_modifier(Modifier::BOLD),
            ConnStatus::Connecting => Style::default().fg(conn_color),
            ConnStatus::Idle => Style::default()
                .fg(Color::DarkGray)
                .add_modifier(Modifier::DIM),
        };
        lines.push(Line::from(vec![
            Span::styled(format!("{} ", status.shape()), dot_style),
            Span::styled(c.name.clone(), name_style),
        ]));
        if sidebar_db_row(app) {
            let label = sidebar_db_label(app);
            let w = (area.width as usize).saturating_sub(4).max(6);
            lines.push(Line::from(vec![
                Span::styled("▤ ", Style::default().fg(Color::Cyan)),
                Span::styled(
                    truncate_disp(&label, w),
                    Style::default()
                        .fg(Color::Cyan)
                        .add_modifier(Modifier::BOLD),
                ),
            ]));
        }
        render_redis_sidebar(f, area, app, &mut lines);
        return;
    }

    // SQL / MongoDB: the connection → database → table tree (R43).
    rebuild_side_rows(app);
    let mut lines: Vec<Line> = Vec::new();

    // filter row: the active `/` filter, the `f` quick search, or the hints.
    let searching = app.tree_search_prompt.is_some();
    let filter_rows = if app.tables_all.is_empty() && !searching {
        0
    } else {
        1
    };
    if filter_rows > 0 {
        let w = (area.width as usize).saturating_sub(4).max(6);
        let (mark, text, style) = if searching {
            let (mark, text) = if app.tree_search.is_empty() {
                ("f ", t("f 搜索连接 / 库 / 表").to_string())
            } else {
                (
                    "▸ ",
                    format!("f{} · {}", app.tree_search, tree_search_hits(app)),
                )
            };
            (mark, text, Style::default().fg(Color::Magenta))
        } else if app.table_filter.is_empty() {
            (
                "/ ",
                t("/ 过滤表名").to_string(),
                Style::default().fg(Color::DarkGray),
            )
        } else {
            (
                "▸ ",
                format!(
                    "/{} · {}/{}",
                    app.table_filter,
                    app.tables.len(),
                    app.tables_all.len()
                ),
                Style::default().fg(Color::Yellow),
            )
        };
        lines.push(Line::from(vec![
            Span::styled(mark, Style::default().fg(Color::Yellow)),
            Span::styled(truncate_disp(&text, w), style),
        ]));
    }

    let cap = (area.height as usize)
        .saturating_sub(2 + filter_rows)
        .max(1);
    let n = app.side_rows.len();
    let sel = if n == 0 { 0 } else { app.side_sel.min(n - 1) };
    let start = if n <= cap {
        0
    } else {
        sel.saturating_sub(cap / 2).min(n - cap)
    };
    let needle = if searching {
        app.tree_search.trim().to_ascii_lowercase()
    } else {
        app.table_filter.trim().to_ascii_lowercase()
    };
    for i in start..(start + cap).min(n) {
        let row = app.side_rows[i].clone();
        lines.push(side_row_line(app, &row, i == sel, &needle, area.width));
    }

    let title = if app.table_filter.is_empty() {
        format!(" {} ({}) ", c.name, app.tables_all.len())
    } else {
        tf(
            " {} 表 {}/{} ",
            &[&(c.name), &(app.tables.len()), &(app.tables_all.len())],
        )
    };
    f.render_widget(
        Paragraph::new(lines).block(
            Block::default()
                .borders(Borders::ALL)
                .title(title)
                .border_set(border::ROUNDED)
                .border_style(border_style(focused)),
        ),
        area,
    );
}

/// Render one row of the sidebar connection tree: an expand triangle, a
/// connection / database symbol and the name, indented two cells per level. The
/// selected row is filled so the single tree cursor is unmistakable.
fn side_row_line(
    app: &App,
    row: &SideRow,
    selected: bool,
    needle: &str,
    area_w: u16,
) -> Line<'static> {
    let depth = side_row_depth(row);
    let indent = "  ".repeat(depth);
    let mk = |s: Style| -> Style {
        if selected {
            s.bg(Color::DarkGray).add_modifier(Modifier::BOLD)
        } else {
            s
        }
    };
    let inner = (area_w as usize).saturating_sub(2 + indent.len()).max(4);
    let mut spans: Vec<Span> = vec![Span::styled(indent, mk(Style::default()))];
    match row {
        SideRow::Group {
            id,
            name,
            depth: _,
            count,
            open,
        } => {
            spans.push(Span::styled(
                if *open { "▾ " } else { "▸ " }.to_string(),
                mk(Style::default().fg(Color::DarkGray)),
            ));
            spans.push(Span::styled(
                "📁 ".to_string(),
                mk(Style::default().fg(Color::Yellow)),
            ));
            let badge = format!(" [{count}]");
            let name_w = inner.saturating_sub(disp_width(&badge));
            // R55: while this group is being renamed, draw the live edit buffer
            // (with a caret) in place of the name.
            let editing = app
                .rename_edit
                .as_ref()
                .filter(|e| matches!(&e.target, RenameTarget::Group { id: gid } if gid == id));
            match editing {
                Some(e) => spans.push(Span::styled(
                    format!("{}▏", e.text),
                    mk(Style::default()
                        .fg(Color::Yellow)
                        .add_modifier(Modifier::BOLD)),
                )),
                None => spans.push(Span::styled(
                    truncate_disp(name, name_w),
                    mk(Style::default().add_modifier(Modifier::BOLD)),
                )),
            }
            spans.push(Span::styled(
                badge,
                mk(Style::default().fg(Color::DarkGray)),
            ));
            // The group's fold memory is keyed by id, so a filter that hides
            // then reveals it keeps the user's choice.
            let _ = id;
        }
        SideRow::Conn { idx, .. } => {
            let (cid, name, color, open, ro) = match side_root_cfg(app, *idx) {
                Some(c) => (
                    c.id.clone(),
                    c.name.clone(),
                    connection_color(c),
                    side_conn_open(app, *idx),
                    c.read_only,
                ),
                None => (String::new(), String::new(), Color::Gray, false, false),
            };
            let status = side_conn_status(app, *idx);
            spans.push(Span::styled(
                if open { "▾ " } else { "▸ " }.to_string(),
                mk(Style::default().fg(Color::DarkGray)),
            ));
            // R47b: shape carries the state (● active / ○ idle / ◐ connecting),
            // the connection colour carries identity. Idle dots are dimmed so a
            // disconnected root reads as muted without losing its colour.
            let dot_style = match status {
                ConnStatus::Active => Style::default().fg(color),
                ConnStatus::Connecting => Style::default().fg(color).add_modifier(Modifier::BOLD),
                ConnStatus::Idle => Style::default().fg(color).add_modifier(Modifier::DIM),
            };
            spans.push(Span::styled(format!("{} ", status.shape()), mk(dot_style)));
            if ro {
                spans.push(Span::styled(
                    "🔒 ".to_string(),
                    mk(Style::default().fg(color)),
                ));
            }
            // R55: while this root is being renamed, draw the live edit buffer
            // (with a caret) instead of the name.
            let editing = app
                .rename_edit
                .as_ref()
                .filter(|e| matches!(&e.target, RenameTarget::Conn { id } if *id == cid));
            if let Some(e) = editing {
                spans.push(Span::styled(
                    format!("{}▏", e.text),
                    mk(Style::default()
                        .fg(Color::Yellow)
                        .add_modifier(Modifier::BOLD)),
                ));
                return Line::from(spans);
            }
            let name_w = inner.saturating_sub(if ro { 2 } else { 0 });
            // A disconnected root's name is muted grey so it cannot be mistaken
            // for a live connection at a glance.
            let name_style = match status {
                ConnStatus::Active => Style::default().fg(color).add_modifier(Modifier::BOLD),
                ConnStatus::Connecting => Style::default().fg(color),
                ConnStatus::Idle => Style::default()
                    .fg(Color::DarkGray)
                    .add_modifier(Modifier::DIM),
            };
            spans.push(Span::styled(truncate_disp(&name, name_w), mk(name_style)));
        }
        SideRow::ConnLoading { .. } => {
            spans.push(Span::styled(
                truncate_disp(t("… 加载库列表"), inner + 2),
                mk(Style::default().fg(Color::DarkGray)),
            ));
        }
        SideRow::ConnError { msg, .. } => {
            spans.push(Span::styled(
                format!("✗ {}", truncate_disp(msg, inner)),
                mk(Style::default().fg(Color::Red)),
            ));
        }
        SideRow::Db { idx, db, .. } => {
            let is_cur = side_is_active(app, *idx);
            let is_cur_db = is_cur && *db == app.current_db();
            let open = is_cur_db
                && side_root_cfg(app, *idx)
                    .is_some_and(|c| !app.tree_db_closed.contains(&db_node_key(&c.id, db)));
            let tri = if is_cur_db && open { "▾ " } else { "▸ " };
            spans.push(Span::styled(
                tri.to_string(),
                mk(Style::default().fg(Color::DarkGray)),
            ));
            spans.push(Span::styled(
                "▤ ".to_string(),
                mk(Style::default().fg(Color::Cyan)),
            ));
            let disp = fix_double_encoding(db);
            // R47b: a database under a disconnected connection is a cached,
            // muted row — still visible so the tree keeps its shape, but dimmed
            // so it reads as stale. Clicking it reconnects (switch_to_db).
            let live = side_root_cfg(app, *idx).is_some_and(|c| conn_is_live(app, &c.id));
            let mut style = Style::default()
                .fg(if is_cur { Color::Cyan } else { Color::Gray })
                .add_modifier(Modifier::BOLD);
            if !live {
                style = style.add_modifier(Modifier::DIM);
            }
            let style = mk(style);
            let hit = style.add_modifier(Modifier::UNDERLINED);
            spans.extend(highlight_match_spans(
                &truncate_disp(&disp, inner),
                needle,
                style,
                hit,
            ));
        }
        SideRow::Table { table, .. } => {
            let view = app
                .tables
                .get(*table)
                .is_some_and(|t| t.table_type.eq_ignore_ascii_case("VIEW"));
            let name = app
                .tables
                .get(*table)
                .map(|t| fix_double_encoding(&qualified_display(&app.schema, &t.name)))
                .unwrap_or_default();
            let w = inner.saturating_sub(usize::from(view));
            let disp = truncate_table_name(&name, w);
            let style = mk(if view {
                Style::default().fg(Color::Blue)
            } else {
                Style::default()
            });
            let hit = style.add_modifier(Modifier::UNDERLINED);
            spans.extend(highlight_match_spans(&disp, needle, style, hit));
            if view {
                spans.push(Span::styled(
                    "~".to_string(),
                    mk(Style::default().fg(Color::Blue)),
                ));
            }
        }
    }
    // R45 size column: right-aligned + muted. It only appears when the terminal
    // is wide enough (<56 hides it so the table name keeps the width).
    if let Some(size) = side_row_size(app, row) {
        let full_w = (area_w as usize).saturating_sub(2);
        let used: usize = spans.iter().map(|s| disp_width(&s.content)).sum();
        let size_w = disp_width(&size);
        let pad = full_w.saturating_sub(used + size_w);
        if pad > 0 {
            spans.push(Span::styled(" ".repeat(pad), mk(Style::default())));
        }
        spans.push(Span::styled(size, mk(Style::default().fg(Color::DarkGray))));
    }
    // R50: a selected row fills the whole inner width so the highlight reads as
    // one solid band instead of stopping at the last glyph. The size column
    // already pads its own row, so this tops up whatever is still missing (and
    // pads the rows that have no size cell at all) — never a double pad. The
    // width is measured with `disp_width`, so wide emoji (`📁` / `▤` / `🔒`)
    // count as the two cells they actually occupy.
    if selected {
        let full_w = (area_w as usize).saturating_sub(2);
        let used: usize = spans.iter().map(|s| disp_width(&s.content)).sum();
        let pad = full_w.saturating_sub(used);
        if pad > 0 {
            spans.push(Span::styled(" ".repeat(pad), mk(Style::default())));
        }
    }
    Line::from(spans)
}

/// The right-aligned size cell for a database (`2.1 GB`) or table (`1.2k` row
/// estimate) row, or `None` when there is nothing (or no room) to show (R45).
fn side_row_size(app: &App, row: &SideRow) -> Option<String> {
    // Width first: a narrow screen gives every cell to the name.
    if app.term_w < 56 {
        return None;
    }
    match row {
        SideRow::Db { db, .. } => match app.db_size_state.get(db) {
            Some(TreeDbState::Loading) => Some("…".to_string()),
            Some(TreeDbState::Error(_)) => Some("✗".to_string()),
            None => app
                .db_sizes
                .get(db)
                .and_then(|i| i.total_bytes)
                .map(human_bytes),
        },
        SideRow::Table { table, .. } => {
            let name = app.tables.get(*table)?.name.to_lowercase();
            app.db_sizes
                .get(&app.current_db())
                .and_then(|i| i.rows.get(&name))
                .map(|n| human_count(*n))
        }
        _ => None,
    }
}

/// Single-letter type badge shown next to a key in the sidebar.
fn redis_type_badge(t: &str) -> (&'static str, Color) {
    match t.to_ascii_lowercase().as_str() {
        "string" => ("S", Color::Green),
        "list" => ("L", Color::Yellow),
        "set" => ("E", Color::Cyan),
        "zset" => ("Z", Color::Magenta),
        "hash" => ("H", Color::Blue),
        "stream" => ("X", Color::LightRed),
        "rejson-rl" | "json" => ("J", Color::LightYellow),
        _ => ("?", Color::DarkGray),
    }
}

/// The type badge shown for one key. On a narrow screen the TTL fuses into the
/// badge (`S·12s`) so the key name keeps its width and the row never wraps
/// (R42).
fn redis_badge_token(narrow: bool, badge: &str, ttl: Option<i64>) -> String {
    match (narrow, ttl) {
        (true, Some(t)) => format!("{badge}·{t}s"),
        _ => badge.to_string(),
    }
}

/// Sidebar body for a Redis connection: a `/` pattern row followed by the SCAN
/// key list with type + TTL badges.
fn render_redis_sidebar(f: &mut Frame, area: Rect, app: &App, lines: &mut Vec<Line>) {
    let focused = app.focus == Focus::Sidebar;
    let w = (area.width as usize).saturating_sub(4).max(6);
    let needle = app.redis_filter.trim().to_lowercase();
    // pattern row (server-side SCAN MATCH) + client-side filter row (R42).
    let (mark, text, style) = if app.redis_scan.pattern == "*" {
        (
            "/ ",
            t("/ 匹配模式（SCAN MATCH）").to_string(),
            Style::default().fg(Color::DarkGray),
        )
    } else {
        (
            "▸ ",
            format!(
                "/{} · {} keys",
                app.redis_scan.pattern,
                app.redis_scan.keys.len()
            ),
            Style::default().fg(Color::Yellow),
        )
    };
    lines.push(Line::from(vec![
        Span::styled(mark, Style::default().fg(Color::Yellow)),
        Span::styled(truncate_disp(&text, w), style),
    ]));
    if !app.redis_filter.is_empty() {
        lines.push(Line::from(vec![
            Span::styled("f ", Style::default().fg(Color::Yellow)),
            Span::styled(
                truncate_disp(
                    &tf(
                        "{} · {} 命中",
                        &[&app.redis_filter, &(app.redis_scan.keys.len())],
                    ),
                    w,
                ),
                Style::default().fg(Color::Yellow),
            ),
        ]));
    }

    // Header rows: connection + db row + pattern row (+ filter row).
    let extra = if app.redis_filter.is_empty() { 0 } else { 1 };
    let cap = (area.height as usize).saturating_sub(5 + extra).max(1);
    let n = app.redis_scan.keys.len();
    let sel = app.redis_list.selected();
    let start = sel
        .unwrap_or(0)
        .saturating_sub(cap / 2)
        .min(n.saturating_sub(cap.min(n)));
    // On a narrow screen the type badge and TTL fuse into one `S·12s` token so a
    // key row always stays on a single line (R42). 42-column terminals (the
    // small-screen acceptance size) give the sidebar ~28 columns, so the
    // threshold sits just above that.
    let narrow = area.width < 30;
    for (i, key) in app.redis_scan.keys.iter().enumerate().skip(start).take(cap) {
        let (badge, color) = redis_type_badge(&key.key_type);
        let ttl_num = (key.ttl >= 0).then_some(key.ttl);
        let badge_token = redis_badge_token(narrow, badge, ttl_num);
        let ttl = if narrow {
            String::new()
        } else {
            ttl_num.map(|t| format!(" {t}s")).unwrap_or_default()
        };
        let picked = app.redis_selected.contains(&key.key_raw);
        let marker = if sel == Some(i) { "▸" } else { " " };
        let check = if picked { "[x]" } else { "[ ]" };
        let check_style = if picked {
            Style::default()
                .fg(Color::Green)
                .add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::DarkGray)
        };
        let prefix_w = 2 + badge_token.chars().count() + 1 + ttl.len();
        let name_w = w.saturating_sub(prefix_w).max(4);
        let name = truncate_disp(&fix_double_encoding(&key.key_display), name_w);
        let row_style = if sel == Some(i) {
            Style::default()
                .fg(Color::Green)
                .add_modifier(Modifier::BOLD)
        } else {
            Style::default()
        };
        let mut spans = vec![
            Span::styled(marker, row_style),
            Span::styled(check, check_style),
            Span::styled(
                badge_token,
                Style::default().fg(color).add_modifier(Modifier::BOLD),
            ),
            Span::styled(" ", row_style),
        ];
        spans.extend(highlight_match_spans(
            &name,
            &needle,
            row_style,
            search_hit_style(),
        ));
        if !ttl.is_empty() {
            spans.push(Span::styled(ttl, Style::default().fg(Color::DarkGray)));
        }
        lines.push(Line::from(spans));
    }
    if !app.redis_scan.exhausted {
        lines.push(Line::from(Span::styled(
            t("  n 加载更多…"),
            Style::default().fg(Color::DarkGray),
        )));
    } else if n == 0 {
        lines.push(Line::from(Span::styled(
            if app.redis_filter.is_empty() {
                t("  （无匹配 key）").to_string()
            } else {
                tf("  （无「{}」命中）", &[&app.redis_filter])
            },
            Style::default().fg(Color::DarkGray),
        )));
    }

    let conn = app
        .selected
        .as_ref()
        .map(|c| c.name.clone())
        .unwrap_or_default();
    let title = if app.redis_selected.is_empty() {
        format!(" {} · {} keys ", conn, n)
    } else {
        tf(
            " {} · {} keys · 已选 {} ",
            &[&(conn), &(n), &(app.redis_selected.len())],
        )
    };
    f.render_widget(
        Paragraph::new(lines.clone()).block(
            Block::default()
                .borders(Borders::ALL)
                .title(title)
                .border_set(border::ROUNDED)
                .border_style(border_style(focused)),
        ),
        area,
    );
}

/// Rendered value of one form row (passwords masked).
fn form_row_value(f: &ConnForm, row: FormRow) -> String {
    match row {
        FormRow::Name => f.name.clone(),
        FormRow::DbType => f.db_type.clone(),
        FormRow::Host => f.host.clone(),
        FormRow::Port => f.port.clone(),
        FormRow::Username => f.username.clone(),
        FormRow::Password => "*".repeat(f.password.chars().count()),
        FormRow::Database => f.database.clone(),
        FormRow::QueryTimeout => {
            let v = f.query_timeout.trim();
            if v.is_empty() {
                t("默认（60s）").to_string()
            } else if v == "0" {
                t("不限").to_string()
            } else {
                format!("{} s", v)
            }
        }
        FormRow::Ssl => if f.ssl { "y" } else { "n" }.to_string(),
        FormRow::ReadOnly => {
            if f.read_only {
                format!("y  {}", t("拒绝写语句"))
            } else {
                "n".to_string()
            }
        }
        FormRow::Color => {
            if f.color.trim().is_empty() {
                t("无（按类型）").to_string()
            } else {
                f.color.clone()
            }
        }
        FormRow::SshEnabled => if f.ssh_enabled { "y" } else { "n" }.to_string(),
        FormRow::SshHost => f.ssh_host.clone(),
        FormRow::SshPort => f.ssh_port.clone(),
        FormRow::SshUser => f.ssh_user.clone(),
        FormRow::SshAuth => f.ssh_auth.as_str().to_string(),
        FormRow::SshPassword => "*".repeat(f.ssh_password.chars().count()),
        FormRow::SshKeyPath => f.ssh_key_path.clone(),
        FormRow::SshKeyPassphrase => "*".repeat(f.ssh_key_passphrase.chars().count()),
        FormRow::SshAgentSock => f.ssh_agent_sock.clone(),
        FormRow::Save => {
            if f.edit_id.is_some() {
                t("↵ 更新连接").to_string()
            } else {
                t("↵ 保存连接").to_string()
            }
        }
    }
}

fn render_form(f: &mut Frame, area: Rect, app: &mut App) {
    let form = app.form.clone();
    let rows = form_rows(&form);
    let box_w = if app.layout_mode == LayoutMode::Narrow {
        area.width.saturating_sub(2)
    } else {
        52.min(area.width.saturating_sub(4))
    };
    // Two lines are reserved below the fields for the error / type hint.
    let reserved: u16 = 2;
    let want_h = (rows.len() as u16).saturating_add(reserved + 2);
    let box_h = want_h
        .min(area.height.saturating_sub(2))
        .max(3.min(area.height));
    let x = area.x + area.width.saturating_sub(box_w) / 2;
    let y = area.y + area.height.saturating_sub(box_h) / 2;
    let box_area = Rect {
        x,
        y,
        width: box_w,
        height: box_h,
    };

    let inner_h = box_h.saturating_sub(2);
    let visible = inner_h.saturating_sub(reserved).max(1) as usize;
    let active = form.field.min(rows.len().saturating_sub(1));
    let mut scroll = form.scroll.min(rows.len().saturating_sub(visible));
    if active < scroll {
        scroll = active;
    }
    if active >= scroll + visible {
        scroll = active + 1 - visible;
    }
    app.form.scroll = scroll;

    let mut lines: Vec<Line> = Vec::new();
    // R41: on a very narrow terminal the label column shrinks and the SSH
    // section's labels are abbreviated so the value keeps a readable width. The
    // rows themselves already expand / collapse with the tunnel toggle.
    let narrow = app.layout_mode == LayoutMode::Narrow || box_w < 44;
    let label_w = if narrow { 9usize } else { 16 };
    let end = (scroll + visible).min(rows.len());
    for (i, (row, label)) in rows.iter().enumerate().take(end).skip(scroll) {
        let (row, label) = (*row, *label);
        let label = if narrow {
            form_label_short(label)
        } else {
            label
        };
        let is_active = i == active;
        // R58: while the query-timeout row is being edited, show its raw buffer
        // (not the derived `30 s` / `默认（60s）` display) so the caret sits where
        // the next digit will land.
        let mut value = if form.editing && is_active && row == FormRow::QueryTimeout {
            form.query_timeout.clone()
        } else {
            form_row_value(&form, row)
        };
        if form.editing && is_active {
            value.push('▏');
        }
        let marker = if is_active { "▸ " } else { "  " };
        let style = if is_active {
            Style::default()
                .fg(Color::Green)
                .add_modifier(Modifier::BOLD)
        } else {
            Style::default()
        };
        lines.push(Line::from({
            let mut spans = vec![Span::styled(
                format!("{marker}{label:<label_w$} {value}"),
                style,
            )];
            // Read-only colour preview swatch: the connection colour when set,
            // else the database-family default the sidebar will use.
            if row == FormRow::Color {
                let swatch =
                    parse_hex_color(&form.color).unwrap_or_else(|| db_type_color(&form.db_type));
                spans.push(Span::styled("  ███", Style::default().fg(swatch)));
            }
            spans
        }));
        // The kernel forwards the tunnel to the connection's own host:port —
        // there is no separate remote-target field in TransportLayerConfig, so
        // it is shown (and overridden by editing host/port above).
        if row == FormRow::SshAuth && form.ssh_enabled {
            let target_port = if form.port.trim().is_empty() {
                "?".to_string()
            } else {
                form.port.trim().to_string()
            };
            lines.push(Line::from(Span::styled(
                format!(
                    "  {:<label_w$} {}:{}",
                    if narrow { "remote" } else { t("远端目标") },
                    form.host.trim(),
                    target_port
                ),
                Style::default().fg(Color::DarkGray),
            )));
        }
    }
    if !form.err.is_empty() {
        lines.push(Line::from(Span::styled(
            format!("✗ {}", form.err),
            Style::default().fg(Color::Red),
        )));
    } else {
        lines.push(Line::from(Span::styled(
            "types: mysql postgres sqlite redis mongodb clickhouse sqlserver …",
            Style::default().fg(Color::DarkGray),
        )));
    }

    let title = if form.edit_id.is_some() {
        t(" 编辑连接 ")
    } else {
        t(" 新建连接 ")
    };
    let block = Block::default()
        .borders(Borders::ALL)
        .title(title)
        .border_set(border::ROUNDED)
        .border_style(Style::default().fg(Color::Green));
    f.render_widget(Clear, box_area);
    f.render_widget(Paragraph::new(lines).block(block), box_area);
}

/// Height and top offset for a list / picker overlay so it always fits inside
/// `area`. `Clear` (and every ratatui widget) panics when asked to draw outside
/// the buffer, and a tiny terminal makes the naive `area.height - 2` shrink
/// below the three-row border minimum, so the box is clamped to the area here.
/// Center a `w × h` overlay box inside `area`, clamping both dimensions to the
/// area first. ratatui's widgets (and `Clear` in particular) panic when asked to
/// draw outside the buffer, and a tiny terminal can make a fixed overlay taller
/// than the screen, so every centered overlay goes through here.
/// Shared overlay width. On a narrow terminal the box takes the whole width so
/// it stays readable; otherwise it keeps a two-column margin on each side and is
/// capped at `max`. This one helper keeps every overlay's width policy uniform
/// (and is the single place the small-screen fallback is tuned).
fn overlay_width(area_width: u16, max: u16, min_avail: u16) -> u16 {
    let avail = area_width.saturating_sub(4);
    if avail < min_avail {
        area_width
    } else {
        avail.min(max)
    }
}

/// Build an overlay title from a `prefix`, a list of key hints and a `suffix`,
/// dropping whole hints when they do not fit so a title is never cut mid-key.
/// This is the overlay-title counterpart of [`footer_select`]: key hints survive
/// longest, and the border is never clipped through the middle of a hint.
fn overlay_hint_title(width: u16, prefix: &str, hints: &[Hint], suffix: &str) -> String {
    let budget = width.saturating_sub(2) as usize;
    let mut out = prefix.to_string();
    let mut used = disp_width(&out) + disp_width(suffix);
    for (key, desc) in hints {
        let piece = format!(" · {key} {desc}");
        let pw = disp_width(&piece);
        if used + pw <= budget {
            out.push_str(&piece);
            used += pw;
        } else {
            break;
        }
    }
    out.push_str(suffix);
    out
}

fn centered_overlay(area: Rect, w: u16, h: u16) -> Rect {
    let w = w.min(area.width);
    let h = h.min(area.height);
    let x = area.x + area.width.saturating_sub(w) / 2;
    let y = area.y + area.height.saturating_sub(h) / 2;
    Rect {
        x,
        y,
        width: w,
        height: h,
    }
}

/// Pick a title that fits `box_width` (the overlay's outer width). ratatui clips
/// an over-long title mid-word, so a short variant is substituted when the full
/// one would not fit — the R39 "titles are never truncated" rule. Two columns
/// are reserved for the border corners.
fn fit_title(full: &str, short: &str, box_width: u16) -> String {
    if disp_width(full) <= box_width.saturating_sub(2) as usize {
        full.to_string()
    } else {
        short.to_string()
    }
}

fn overlay_list_box(rows: usize, area: Rect) -> (u16, u16) {
    if area.height == 0 {
        return (area.y, 0);
    }
    let want = (rows as u16).saturating_add(2);
    let h = want.min(area.height).max(3.min(area.height));
    let y = area.y + area.height.saturating_sub(h) / 2;
    (y, h)
}

fn render_conn_picker(f: &mut Frame, area: Rect, app: &mut App) {
    let w = area.width.min(if app.layout_mode == LayoutMode::Narrow {
        area.width
    } else {
        56
    });
    let (y, h) = overlay_list_box(app.connections.len(), area);
    let x = area.x + (area.width.saturating_sub(w)) / 2;
    let box_area = Rect {
        x,
        y,
        width: w,
        height: h,
    };
    app.rects.picker = box_area;
    app.rects.picker_visible = true;

    f.render_widget(Clear, box_area);
    let items: Vec<ListItem> = app
        .connections
        .iter()
        .map(|c| {
            let w = (box_area.width as usize).saturating_sub(16);
            let color = connection_color(c);
            ListItem::new(Line::from(vec![
                Span::styled(
                    format!("{:11}", truncate_disp(c.db_type.as_str(), 11)),
                    Style::default().fg(color),
                ),
                Span::raw(" "),
                Span::styled(
                    truncate_disp(&c.name, w),
                    Style::default().fg(color).add_modifier(Modifier::BOLD),
                ),
            ]))
        })
        .collect();
    let list = List::new(items)
        .block(
            Block::default()
                .borders(Borders::ALL)
                // Key hints are added whole, so a narrow picker drops the least
                // important ones instead of clipping `s 排序` into `s…`.
                .title(overlay_hint_title(
                    box_area.width,
                    &format!(" {} ", t("连接")),
                    &[
                        ("↑↓", t("选择连接")),
                        ("Enter", t("连接")),
                        ("c", t("新建")),
                        ("p", t("复制")),
                        ("s", t("排序")),
                        ("x", t("删除")),
                        ("q", t("显隐")),
                    ],
                    " ",
                ))
                .border_set(border::ROUNDED),
        )
        .highlight_style(
            Style::default()
                .bg(Color::DarkGray)
                .add_modifier(Modifier::BOLD),
        );
    f.render_stateful_widget(list, box_area, &mut app.conn_list);
}

fn render_db_picker(f: &mut Frame, area: Rect, app: &mut App) {
    let entries = db_entries(app);
    let cur = db_current_index(app);
    let w = area.width.min(if app.layout_mode == LayoutMode::Narrow {
        area.width
    } else {
        46
    });
    let (y, h) = overlay_list_box(entries.len(), area);
    let x = area.x + (area.width.saturating_sub(w)) / 2;
    let box_area = Rect {
        x,
        y,
        width: w,
        height: h,
    };
    app.rects.db_picker = box_area;
    app.rects.db_picker_visible = true;
    f.render_widget(Clear, box_area);

    let items: Vec<ListItem> = entries
        .iter()
        .enumerate()
        .map(|(i, name)| {
            let style = if i == cur {
                Style::default()
                    .fg(Color::Green)
                    .add_modifier(Modifier::BOLD)
            } else {
                Style::default()
            };
            let mark = if i == cur { "● " } else { "  " };
            ListItem::new(Line::from(vec![
                Span::styled(mark, style),
                Span::styled(
                    truncate_disp(
                        &fix_double_encoding(name),
                        (box_area.width as usize).saturating_sub(6),
                    ),
                    style,
                ),
            ]))
        })
        .collect();
    let title = match app.backend_kind {
        Backend::Redis => t(" Redis db · ↑↓ Enter · Esc 关 "),
        _ if !app.schemas.is_empty() => t(" 模式 / 数据库 · ↑↓ Enter · Esc 关 "),
        _ => t(" 数据库 · ↑↓ Enter · Esc 关 "),
    };
    // The `d` overlay header is tinted by the connection colour (with the name
    // shown) so the switcher belongs visibly to the active connection.
    let accent = app
        .selected
        .as_ref()
        .map(connection_color)
        .unwrap_or(Color::Cyan);
    let title = match app.selected.as_ref() {
        Some(c) => Span::styled(
            format!(" ● {} ·{title}", truncate_disp(&c.name, 16)),
            Style::default().fg(accent).add_modifier(Modifier::BOLD),
        ),
        None => Span::styled(title, Style::default().fg(accent)),
    };
    let list = List::new(items)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .title(title)
                .border_set(border::ROUNDED)
                .border_style(Style::default().fg(accent)),
        )
        .highlight_style(
            Style::default()
                .bg(Color::DarkGray)
                .add_modifier(Modifier::BOLD),
        );
    f.render_stateful_widget(list, box_area, &mut app.db_list);
}

/// Saved-SQL snippet overlay (DBX's `saved_sql_files`). Enter inserts into the
/// editor; `r` reloads from the shared DBX store.
fn render_snippets(f: &mut Frame, area: Rect, app: &mut App) {
    let w = area.width.min(if app.layout_mode == LayoutMode::Narrow {
        area.width
    } else {
        60
    });
    let total = app.snippets.len();
    let shown = app.snippet_view.len();
    let filter_h = if app.snippet_filter.is_some() { 1 } else { 0 };
    let (y, h) = overlay_list_box(shown.max(1) + filter_h, area);
    let x = area.x + (area.width.saturating_sub(w)) / 2;
    let box_area = Rect {
        x,
        y,
        width: w,
        height: h,
    };
    f.render_widget(Clear, box_area);
    let title = if app.snippet_needle.trim().is_empty() {
        fit_title(
            &tf(
                " SQL 收藏 · {} 个 · Enter 插入 · / 过滤 · d 删除 · r 刷新 · Esc 关 ",
                &[&total],
            ),
            t(" SQL 收藏 · Enter 插入 · Esc "),
            box_area.width,
        )
    } else {
        fit_title(
            &tf(
                " SQL 收藏 · 过滤「{}」 {}/{} · Esc 关 ",
                &[&(app.snippet_needle), &shown, &total],
            ),
            t(" SQL 收藏（已过滤）· Esc "),
            box_area.width,
        )
    };
    let block = Block::default()
        .borders(Borders::ALL)
        .title(Span::styled(title, Style::default().fg(Color::Cyan)))
        .border_set(border::ROUNDED)
        .border_style(Style::default().fg(Color::Cyan));
    let inner = block.inner(box_area);
    f.render_widget(block, box_area);
    if inner.width < 4 || inner.height < 1 {
        return;
    }
    let (list_area, filter_area) = if app.snippet_filter.is_some() {
        let chunks = Layout::vertical([Constraint::Min(1), Constraint::Length(1)]).split(inner);
        (chunks[0], Some(chunks[1]))
    } else {
        (inner, None)
    };
    let items: Vec<ListItem> = if shown == 0 {
        let hint = if total == 0 {
            t("暂无收藏 · 编辑器内 Ctrl-O 后按 s 或 Alt-S 添加")
        } else {
            t("（没有匹配的收藏）")
        };
        vec![ListItem::new(Line::from(Span::styled(
            hint,
            Style::default().fg(Color::DarkGray),
        )))]
    } else {
        app.snippet_view
            .iter()
            .filter_map(|&i| app.snippets.get(i))
            .map(|s| {
                let head = s
                    .sql
                    .lines()
                    .find(|l| !l.trim().is_empty())
                    .unwrap_or("")
                    .trim();
                ListItem::new(Line::from(vec![
                    Span::styled(
                        format!("{:20}", truncate_disp(&s.label, 20)),
                        Style::default()
                            .fg(Color::Cyan)
                            .add_modifier(Modifier::BOLD),
                    ),
                    Span::raw(" "),
                    Span::styled(
                        truncate_disp(head, (box_area.width as usize).saturating_sub(24)),
                        Style::default().fg(Color::DarkGray),
                    ),
                ]))
            })
            .collect()
    };
    let list = List::new(items).highlight_style(
        Style::default()
            .bg(Color::DarkGray)
            .add_modifier(Modifier::BOLD),
    );
    f.render_stateful_widget(list, list_area, &mut app.snippet_list);
    if let Some(fa) = filter_area {
        if let Some(ta) = app.snippet_filter.as_mut() {
            ta.set_block(Block::default());
            f.render_widget(&*ta, fa);
        }
    }
    if app.snippet_confirm.is_some() {
        render_snippet_confirm(f, area);
    }
}

/// The `d` delete confirmation for a saved SQL favourite (keyboard-only, like
/// the history delete layer; the overlay swallows mouse input anyway).
fn render_snippet_confirm(f: &mut Frame, area: Rect) {
    let w = area.width.saturating_sub(4).clamp(24, 64);
    let inner_w = w.saturating_sub(2) as usize;
    let msg = t("将删除这条 SQL 收藏（只删本地配置，不影响数据库）");
    let mut lines: Vec<Line> = wrap_text(msg, inner_w.max(1))
        .into_iter()
        .map(|l| {
            Line::from(Span::styled(
                l,
                Style::default().fg(Color::Red).add_modifier(Modifier::BOLD),
            ))
        })
        .collect();
    lines.push(Line::from(""));
    lines.push(Line::from(Span::styled(
        t("Enter/y 执行   Esc/n 取消"),
        Style::default().fg(Color::DarkGray),
    )));
    let h = (lines.len() as u16 + 2).min(area.height.max(3));
    let box_area = centered_overlay(area, w, h);
    f.render_widget(Clear, box_area);
    let block = Block::default()
        .borders(Borders::ALL)
        .title(Span::styled(
            t(" ⚠ 删除收藏确认 "),
            Style::default().fg(Color::Red).add_modifier(Modifier::BOLD),
        ))
        .border_set(border::THICK)
        .border_style(Style::default().fg(Color::Red));
    f.render_widget(Paragraph::new(lines).block(block), box_area);
}

/// Ctrl-Shift-H column-visibility overlay: space toggles the highlighted column,
/// `a` shows all, `x` keeps only the first. Changes apply live behind the popup.
/// R48 `gc`: the column-structure mini popup. A compact, scrollable list of the
/// open table's columns (name / type / PK / NOT NULL / comment) drawn over the
/// results pane, so the columns can be checked while writing SQL without
/// switching to the full `gd` structure view. On a narrow screen it uses the
/// full width; otherwise it caps at 72 columns.
fn render_cols_popup(f: &mut Frame, area: Rect, app: &mut App) {
    let all_rows = cols_popup_rows(app);
    if all_rows.is_empty() {
        app.cols_popup_open = false;
        return;
    }
    let rows: Vec<&ColPopupRow> = all_rows
        .iter()
        .filter(|r| cols_popup_matches(r, &app.cols_popup_needle))
        .collect();
    // R56: the popup carries two extra columns now, so it opens wider than the
    // R48 72-column cap; a narrow terminal still uses the full width.
    let w = if area.width < 48 {
        area.width
    } else {
        area.width.min(96)
    };
    let (y, h) = overlay_list_box(rows.len().max(1), area);
    let x = area.x + (area.width.saturating_sub(w)) / 2;
    let box_area = Rect {
        x,
        y,
        width: w,
        height: h,
    };
    f.render_widget(Clear, box_area);
    let inner_w = box_area.width.saturating_sub(2) as usize;
    let inner_h = h.saturating_sub(2) as usize;
    let max_scroll = rows.len().saturating_sub(inner_h) as u16;
    if app.cols_popup_scroll > max_scroll {
        app.cols_popup_scroll = max_scroll;
    }
    let table = app
        .table_meta
        .as_ref()
        .map(|m| fix_double_encoding(&m.table))
        .unwrap_or_default();
    let needle = app.cols_popup_needle.trim();
    let full = if needle.is_empty() {
        tf(
            " 列结构 · {} · {} 列 · / 过滤 · j/k 滚动 · Esc 关 ",
            &[&table, &rows.len()],
        )
    } else {
        tf(
            " 列结构 · {} · {}/{} 列 · 过滤「{}」· Esc 关 ",
            &[&table, &rows.len(), &all_rows.len(), &needle],
        )
    };
    let items: Vec<Line> = if rows.is_empty() {
        vec![Line::from(Span::styled(
            t("（没有匹配的列）").to_string(),
            Style::default().fg(Color::DarkGray),
        ))]
    } else {
        let layout = cols_popup_layout(&rows, inner_w);
        rows.iter()
            .map(|r| {
                Line::from(Span::styled(
                    cols_popup_line(r, &layout, inner_w),
                    Style::default(),
                ))
            })
            .collect()
    };
    f.render_widget(
        Paragraph::new(items)
            .block(
                Block::default()
                    .borders(Borders::ALL)
                    .title(fit_title(&full, t(" 列结构 · j/k · Esc "), box_area.width))
                    .border_set(border::ROUNDED)
                    .border_style(Style::default().fg(Color::Cyan)),
            )
            .scroll((app.cols_popup_scroll, 0)),
        box_area,
    );
}

fn render_col_picker(f: &mut Frame, area: Rect, app: &mut App) {
    let Some(grid) = app.grid_full.clone() else {
        return;
    };
    let w = area.width.min(if app.layout_mode == LayoutMode::Narrow {
        area.width
    } else {
        52
    });
    let (y, h) = overlay_list_box(grid.columns.len(), area);
    let x = area.x + (area.width.saturating_sub(w)) / 2;
    let box_area = Rect {
        x,
        y,
        width: w,
        height: h,
    };
    f.render_widget(Clear, box_area);
    let items: Vec<ListItem> = grid
        .columns
        .iter()
        .enumerate()
        .map(|(i, name)| {
            let shown = !app.col_hidden.contains(name.as_str());
            let mark = if shown { "[x] " } else { "[ ] " };
            let style = if shown {
                Style::default().fg(Color::Green)
            } else {
                Style::default().fg(Color::DarkGray)
            };
            ListItem::new(Line::from(vec![
                Span::styled(mark, style),
                Span::styled(
                    truncate_disp(
                        &fix_double_encoding(name),
                        (box_area.width as usize).saturating_sub(6),
                    ),
                    style,
                ),
                Span::styled(format!("  {}", i + 1), Style::default().fg(Color::DarkGray)),
            ]))
        })
        .collect();
    let visible = grid
        .columns
        .iter()
        .filter(|c| !app.col_hidden.contains(c.as_str()))
        .count();
    let list = List::new(items)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .title(fit_title(
                    &tf(
                        " 列显示 {}/{} · 空格勾选 · a 全选 · x 仅首列 · Esc 关 ",
                        &[&(visible), &(grid.columns.len())],
                    ),
                    t(" 列显示 · 空格/a/x · Esc "),
                    box_area.width,
                ))
                .border_set(border::ROUNDED)
                .border_style(Style::default().fg(Color::Cyan)),
        )
        .highlight_style(
            Style::default()
                .bg(Color::DarkGray)
                .add_modifier(Modifier::BOLD),
        );
    f.render_stateful_widget(list, box_area, &mut app.col_picker_list);
}

/// Ctrl-Shift-R recent-table overlay: Enter jumps straight to the table.
fn render_recent_tables(f: &mut Frame, area: Rect, app: &mut App) {
    let w = area.width.min(if app.layout_mode == LayoutMode::Narrow {
        area.width
    } else {
        54
    });
    let (y, h) = overlay_list_box(app.recent_tables.len(), area);
    let x = area.x + (area.width.saturating_sub(w)) / 2;
    let box_area = Rect {
        x,
        y,
        width: w,
        height: h,
    };
    f.render_widget(Clear, box_area);
    let cur_db = app.current_db();
    let items: Vec<ListItem> = app
        .recent_tables
        .iter()
        .map(|(db, schema, table)| {
            let here = *db == cur_db;
            ListItem::new(Line::from(vec![
                Span::styled(
                    if here { "● " } else { "○ " },
                    Style::default().fg(if here { Color::Green } else { Color::DarkGray }),
                ),
                Span::styled(
                    fix_double_encoding(&qualified_display(schema, table)),
                    Style::default().add_modifier(Modifier::BOLD),
                ),
                Span::styled(
                    format!("  {}", fix_double_encoding(db)),
                    Style::default().fg(Color::Cyan),
                ),
            ]))
        })
        .collect();
    let list = List::new(items)
        .block(
            Block::default()
                .borders(Borders::ALL)
                .title(t(" 最近表 · ↑↓ Enter 直达 · Esc 关 "))
                .border_set(border::ROUNDED)
                .border_style(Style::default().fg(Color::Cyan)),
        )
        .highlight_style(
            Style::default()
                .bg(Color::DarkGray)
                .add_modifier(Modifier::BOLD),
        );
    f.render_stateful_widget(list, box_area, &mut app.recent_list);
}

/// One non-selectable section header inside the history panel (R45).
fn history_section_header(text: &str, color: Color) -> ListItem<'static> {
    ListItem::new(Line::from(Span::styled(
        text.to_string(),
        Style::default().fg(color).add_modifier(Modifier::BOLD),
    )))
}

/// One history list row: time · ★ · summary · duration · origin · source. On a
/// narrow panel the time shrinks to `HH:MM` and the duration / origin / source
/// columns drop out entirely so the statement summary keeps a usable width
/// (R41 / R45).
fn history_list_item(app: &App, ri: usize, list_w: usize) -> ListItem<'static> {
    let Some(r) = app.history_rows.get(ri) else {
        return ListItem::new(Line::from(""));
    };
    let fav = app.history_favorites.contains(&r.sql);
    let time = if list_w >= 44 {
        history_time_label(&r.executed_at)
    } else {
        history_time_label_short(&r.executed_at)
    };
    let duration = if list_w >= 40 && r.duration_ms > 0 {
        history_duration_label(r.duration_ms)
    } else {
        String::new()
    };
    let origin = if list_w >= 52 {
        history_origin_badge(&r.origin).unwrap_or("").to_string()
    } else {
        String::new()
    };
    let src = if list_w >= 56 {
        truncate_disp(&r.connection_name, 18)
    } else {
        String::new()
    };
    let count = if r.count > 1 {
        format!("×{}", r.count)
    } else {
        String::new()
    };
    let reserved = disp_width(&time)
        + 4
        + disp_width(&src)
        + 2
        + disp_width(&duration)
        + disp_width(&origin)
        + disp_width(&count);
    let summary = truncate_disp(
        &history_summary(&r.sql),
        list_w.saturating_sub(reserved).max(8),
    );
    let sum_style = if r.success {
        Style::default().add_modifier(Modifier::BOLD)
    } else {
        Style::default().fg(Color::Red)
    };
    let mut spans = vec![
        Span::styled(time, Style::default().fg(Color::DarkGray)),
        Span::raw(" "),
        Span::styled(
            if fav { "★" } else { " " },
            Style::default().fg(Color::Yellow),
        ),
        Span::raw(" "),
        Span::styled(summary, sum_style),
    ];
    if !count.is_empty() {
        spans.push(Span::styled(
            format!(" {count}"),
            Style::default()
                .fg(Color::Yellow)
                .add_modifier(Modifier::BOLD),
        ));
    }
    if !duration.is_empty() {
        spans.push(Span::styled(
            format!("  {duration}"),
            Style::default().fg(Color::DarkGray),
        ));
    }
    if !origin.is_empty() {
        spans.push(Span::styled(
            format!(" {origin}"),
            Style::default().fg(Color::Magenta),
        ));
    }
    if !src.is_empty() {
        spans.push(Span::styled(
            format!("  {src}"),
            Style::default().fg(Color::Cyan),
        ));
    }
    ListItem::new(Line::from(spans))
}

/// The query-history overlay (`Alt-H`): a list of recent statements on top and a
/// wrapped preview of the focused statement below. The `/` filter input takes
/// the bottom slot while it is being typed.
fn render_history_panel(f: &mut Frame, area: Rect, app: &mut App) {
    if area.width < 10 || area.height < 5 {
        return;
    }
    let w = if area.width > 108 {
        104
    } else {
        area.width.saturating_sub(2).max(8)
    };
    let h = area.height.saturating_sub(1).max(3);
    let box_area = centered_overlay(area, w, h);
    f.render_widget(Clear, box_area);

    let total = app.history_rows.len();
    let shown = app.history_view.len();
    let title = if app.history_needle.trim().is_empty() {
        fit_title(
            &tf(
                " 查询历史 · {} 条 · Enter 回填 · Ctrl-↵ 直跑 · f 收藏 · Del 删除 · y 复制 · / 搜索 · Esc 关 ",
                &[&total],
            ),
            t(" 查询历史 · Enter 回填 · Ctrl-↵ 直跑 · Esc "),
            box_area.width,
        )
    } else {
        fit_title(
            &tf(
                " 查询历史 · 过滤「{}」 {}/{} · Esc 关 ",
                &[&(app.history_needle), &shown, &total],
            ),
            t(" 查询历史（已过滤）· Esc "),
            box_area.width,
        )
    };
    let block = Block::default()
        .borders(Borders::ALL)
        .border_set(border::ROUNDED)
        .border_style(Style::default().fg(Color::Cyan))
        .title(Span::styled(title, Style::default().fg(Color::Cyan)));
    let inner = block.inner(box_area);
    f.render_widget(block, box_area);
    if inner.width < 4 || inner.height < 2 {
        return;
    }

    let list_w = inner.width as usize;
    let fav_count = history_fav_count(app);
    let mut items: Vec<ListItem> = Vec::new();
    // View index → display index (the section headers occupy slots too).
    let mut display_of: Vec<usize> = Vec::with_capacity(app.history_view.len());
    if app.history_view.is_empty() {
        items.push(ListItem::new(Line::from(Span::styled(
            t("（没有匹配的历史记录）"),
            Style::default().fg(Color::DarkGray),
        ))));
    } else {
        // Favourites get their own section pinned above the chronological list
        // (R45); `f` moves an entry between the two.
        if fav_count > 0 {
            items.push(history_section_header(
                &tf("★ 收藏 · {}", &[&fav_count]),
                Color::Yellow,
            ));
        }
        for (vi, &ri) in app.history_view.iter().enumerate() {
            if vi == fav_count && fav_count < app.history_view.len() {
                items.push(history_section_header(
                    &tf("─ 时间序 · {}", &[&(app.history_view.len() - fav_count)]),
                    Color::DarkGray,
                ));
            }
            display_of.push(items.len());
            items.push(history_list_item(app, ri, list_w));
        }
    }
    let list = List::new(items).highlight_style(
        Style::default()
            .bg(Color::DarkGray)
            .add_modifier(Modifier::BOLD),
    );
    // Section headers are not selectable: map the cursor onto its display slot
    // and let the list scroll the selection into view (a fresh state each frame
    // is fine; `List` re-derives its offset from the selection).
    let mut list_state = ListState::default();
    if let Some(sel) = app.history_list.selected() {
        if let Some(&d) = display_of.get(sel) {
            list_state.select(Some(d));
        }
    }

    // Too short to split: show the list alone rather than squeezing three panes.
    if inner.height < 6 {
        f.render_stateful_widget(list, inner, &mut list_state);
        return;
    }

    let filter_h = if app.history_filter.is_some() { 3 } else { 0 };
    let region = inner.height.saturating_sub(1 + filter_h);
    let list_h = ((region as u32 * 45 / 100) as u16).clamp(1, region.max(1));
    let preview_h = region.saturating_sub(list_h).max(1);
    let chunks = Layout::vertical([
        Constraint::Length(list_h),
        Constraint::Length(preview_h),
        Constraint::Length(1),
        Constraint::Length(filter_h),
    ])
    .split(inner);
    f.render_stateful_widget(list, chunks[0], &mut list_state);
    f.render_widget(
        Paragraph::new(Line::from(Span::styled(
            "─".repeat(chunks[2].width as usize),
            Style::default().fg(Color::DarkGray),
        ))),
        chunks[2],
    );

    if let Some(ta) = app.history_filter.as_mut() {
        ta.set_block(Block::default());
        f.render_widget(&*ta, chunks[3]);
        return;
    }

    let sel_sql = history_selected_row(app)
        .map(|r| r.sql.clone())
        .unwrap_or_default();
    let lines = wrap_text(&sel_sql, chunks[1].width.max(1) as usize);
    let truncated = lines.len() > 40;
    let mut shown: Vec<Line> = lines
        .iter()
        .take(40)
        .map(|l| Line::from(Span::styled(l.clone(), Style::default().fg(Color::White))))
        .collect();
    if truncated {
        shown.push(Line::from(Span::styled(
            tf("…（预览截断，共 {} 行）", &[&(lines.len())]),
            Style::default().fg(Color::DarkGray),
        )));
    }
    f.render_widget(Paragraph::new(shown), chunks[1]);
}

/// The red confirmation layer for deleting one query-history entry.
/// Returns the `[ 执行 ]` / `[ 取消 ]` hit rectangles (empty when the button row
/// is clipped away).
fn render_history_confirm(f: &mut Frame, area: Rect, hc: &HistoryConfirm) -> (Rect, Rect) {
    let w = if area.width < 30 {
        area.width
    } else {
        area.width.saturating_sub(4).min(72)
    };
    let inner_w = w.saturating_sub(4) as usize;
    let sql_lines = wrap_sql_lines(&hc.sql, inner_w.max(1));
    let max_h = area.height.saturating_sub(2) as usize;
    let h = (sql_lines.len() + 5).min(max_h).max(3) as u16;
    let box_area = centered_overlay(area, w, h);
    f.render_widget(Clear, box_area);
    let mut lines: Vec<Line> = vec![
        Line::from(Span::styled(
            t("⚠ 将删除这条查询历史（不可撤销；不影响数据库数据）"),
            Style::default().fg(Color::Red).add_modifier(Modifier::BOLD),
        )),
        Line::from(""),
    ];
    let room = (box_area.height as usize).saturating_sub(4);
    for l in sql_lines.iter().take(room) {
        lines.push(Line::from(Span::styled(
            l.clone(),
            Style::default().fg(Color::White),
        )));
    }
    lines.push(Line::from(""));
    let inner = Rect {
        x: box_area.x + 1,
        y: box_area.y + 1,
        width: box_area.width.saturating_sub(2),
        height: box_area.height.saturating_sub(2),
    };
    let (buttons, ok, cancel) = confirm_buttons(
        inner,
        inner.y + lines.len() as u16,
        t("Enter/y 执行"),
        t("Esc/n 取消"),
    );
    lines.push(buttons);
    let block = Block::default()
        .borders(Borders::ALL)
        .title(Span::styled(
            t(" ⚠ 删除历史确认 "),
            Style::default().fg(Color::Red).add_modifier(Modifier::BOLD),
        ))
        .border_set(border::THICK)
        .border_style(Style::default().fg(Color::Red));
    f.render_widget(Paragraph::new(lines).block(block), box_area);
    (ok, cancel)
}

/// The `/` table-name filter prompt, drawn as a one-line box at the bottom.
/// Highlight every case-insensitive occurrence of `needle` inside `text`. Used
/// by the global-search list so a hit is visible at a glance.
fn search_highlight(text: &str, needle: &str, base: Style, hit: Style) -> Vec<Span<'static>> {
    let nchars = needle.chars().count();
    if nchars == 0 {
        return vec![Span::styled(text.to_string(), base)];
    }
    let nlow = needle.to_lowercase();
    let chars: Vec<char> = text.chars().collect();
    let mut spans: Vec<Span<'static>> = Vec::new();
    let mut plain = String::new();
    let mut i = 0usize;
    while i < chars.len() {
        let rest: String = chars[i..].iter().collect();
        if i + nchars <= chars.len() && rest.to_lowercase().starts_with(&nlow) {
            if !plain.is_empty() {
                spans.push(Span::styled(std::mem::take(&mut plain), base));
            }
            let matched: String = chars[i..i + nchars].iter().collect();
            spans.push(Span::styled(matched, hit));
            i += nchars;
        } else {
            plain.push(chars[i]);
            i += 1;
        }
    }
    if !plain.is_empty() {
        spans.push(Span::styled(plain, base));
    }
    if spans.is_empty() {
        spans.push(Span::styled(String::new(), base));
    }
    spans
}

/// The global-search overlay (`Alt-G`): one row per hit with the table / column
/// and the matched value (needle highlighted). A running scan shows `done/total`.
fn render_search_panel(f: &mut Frame, area: Rect, app: &mut App) {
    if area.width < 10 || area.height < 5 {
        return;
    }
    let w = if area.width > 108 {
        104
    } else {
        area.width.saturating_sub(2).max(8)
    };
    let h = area.height.saturating_sub(1).max(3);
    let box_area = centered_overlay(area, w, h);
    f.render_widget(Clear, box_area);

    let done = app.search_hits.len();
    let progress = app
        .search_progress
        .map(|(d, total)| tf(" · {}/{} 表", &[&d, &total]))
        .unwrap_or_default();
    let cap = if app.search_truncated {
        tf(" · 上限 {}", &[&SEARCH_MAX_HITS])
    } else {
        String::new()
    };
    let skip = if app.search_skipped.is_empty() {
        String::new()
    } else {
        tf(" · 跳过 {}", &[&(app.search_skipped.len())])
    };
    let title = tf(
        " 全库搜索「{}」· {} 命中{}{}{} · Enter 定位 · y 复制 · r 重搜 · Esc 关 ",
        &[&(app.search_query), &done, &cap, &skip, &progress],
    );
    let title = fit_title(
        &title,
        &tf(" 全库搜索「{}」· {} 命中 ", &[&(app.search_query), &done]),
        box_area.width,
    );
    let block = Block::default()
        .borders(Borders::ALL)
        .border_set(border::ROUNDED)
        .border_style(Style::default().fg(Color::Magenta))
        .title(Span::styled(title, Style::default().fg(Color::Magenta)));
    let inner = block.inner(box_area);
    f.render_widget(block, box_area);
    if inner.width < 4 || inner.height < 1 {
        return;
    }

    if app.search_hits.is_empty() {
        let msg = if app.search_running {
            tf("扫描中…{}", &[&progress])
        } else {
            t("（没有命中）").to_string()
        };
        f.render_widget(
            Paragraph::new(Line::from(Span::styled(
                msg,
                Style::default().fg(Color::DarkGray),
            ))),
            inner,
        );
        return;
    }

    let list_w = inner.width as usize;
    let items: Vec<ListItem> = app
        .search_hits
        .iter()
        .map(|hit| {
            let loc = format!(
                "{}.{}",
                qualified_display(&hit.schema, &hit.table),
                hit.column
            );
            let loc = truncate_disp(&loc, (list_w / 3).clamp(8, 40));
            let matched = truncate_disp(
                &one_line(&hit.matched),
                list_w.saturating_sub(loc.chars().count() + 3).max(8),
            );
            let mut spans = vec![
                Span::styled(
                    loc,
                    Style::default()
                        .fg(Color::Cyan)
                        .add_modifier(Modifier::BOLD),
                ),
                Span::raw(" "),
            ];
            spans.extend(search_highlight(
                &matched,
                &app.search_query,
                Style::default().fg(Color::White),
                Style::default()
                    .fg(Color::Yellow)
                    .add_modifier(Modifier::BOLD),
            ));
            ListItem::new(Line::from(spans))
        })
        .collect();
    let list = List::new(items).highlight_style(
        Style::default()
            .bg(Color::DarkGray)
            .add_modifier(Modifier::BOLD),
    );
    f.render_stateful_widget(list, inner, &mut app.search_list);
}

/// The global-search term prompt, drawn as a one-line box at the bottom.
fn render_search_input(f: &mut Frame, area: Rect, app: &mut App) {
    if area.height < 3 || area.width < 12 {
        return;
    }
    let w = area.width.saturating_sub(4).max(20).min(area.width);
    let h = 3.min(area.height);
    let x = area.x + (area.width.saturating_sub(w)) / 2;
    let y = area.y + area.height.saturating_sub(h + 1);
    let box_area = Rect {
        x,
        y,
        width: w,
        height: h,
    };
    f.render_widget(Clear, box_area);
    let block = Block::default()
        .borders(Borders::ALL)
        .title(fit_title(
            &tf(
                " 全库搜索 · {} · Enter 开始 · Esc 取消 ",
                &[&(app.selected_name())],
            ),
            t(" 全库搜索 · Enter 开始 "),
            box_area.width,
        ))
        .border_set(border::ROUNDED)
        .border_style(Style::default().fg(Color::Magenta));
    let inner = block.inner(box_area);
    f.render_widget(block, box_area);
    if let Some(ta) = app.search_input.as_mut() {
        ta.set_block(Block::default());
        f.render_widget(&*ta, inner);
    }
}

/// One row of the column diff list. Wide screens show `src → tgt`; a narrow
/// screen folds to the mark + the changed-attribute summary.
fn diff_col_line(row: &ColDiffRow, width: usize, narrow: bool) -> Line<'static> {
    let same = row.mark == DiffMark::Same;
    let mark = Span::styled(
        format!(" {} ", row.mark.sign()),
        Style::default()
            .fg(row.mark.color())
            .add_modifier(Modifier::BOLD),
    );
    let name_style = if same {
        Style::default().fg(Color::DarkGray)
    } else {
        Style::default()
            .fg(Color::White)
            .add_modifier(Modifier::BOLD)
    };
    let name = Span::styled(
        truncate_disp(&fix_double_encoding(&row.name), 20),
        name_style,
    );
    let rest = if narrow {
        row.detail.clone()
    } else {
        match row.mark {
            DiffMark::Add => row.src.clone(),
            DiffMark::Drop => row.tgt.clone(),
            DiffMark::Modify => format!("{}  →  {}", row.src, row.tgt),
            DiffMark::Same => row.src.clone(),
        }
    };
    // An unmapped cross-dialect type is flagged with `?` (the detail line always
    // carries it; the wide layout gets it prepended).
    let rest = if !narrow && row.detail.contains("type ?") {
        format!("? {rest}")
    } else {
        rest
    };
    let room = width.saturating_sub(24).max(6);
    let rest = Span::styled(
        truncate_disp(&one_line(&rest), room),
        if same {
            Style::default().fg(Color::DarkGray)
        } else {
            Style::default().fg(Color::Gray)
        },
    );
    Line::from(vec![mark, name, Span::raw("  "), rest])
}

/// One row of the index diff list.
fn diff_index_line(row: &IndexDiffRow, width: usize) -> Line<'static> {
    let same = row.mark == DiffMark::Same;
    let mark = Span::styled(
        format!(" {} ", row.mark.sign()),
        Style::default()
            .fg(row.mark.color())
            .add_modifier(Modifier::BOLD),
    );
    let text = if same {
        row.detail.clone()
    } else if row.mark == DiffMark::Drop {
        row.tgt.clone()
    } else {
        row.detail.clone()
    };
    Line::from(vec![
        mark,
        Span::styled(
            truncate_disp(&one_line(&text), width.saturating_sub(3).max(6)),
            if same {
                Style::default().fg(Color::DarkGray)
            } else {
                Style::default().fg(Color::Gray)
            },
        ),
    ])
}

/// The `Alt-D` target picker overlay.
fn render_diff_picker(f: &mut Frame, area: Rect, app: &mut App) {
    let Some((mode, stage, kind)) = app.diff_picker.as_ref().map(|p| (p.mode, p.stage, p.kind))
    else {
        return;
    };
    if area.width < 12 || area.height < 5 {
        return;
    }
    let src = match diff_source(app) {
        Some((_, schema, table)) => fix_double_encoding(&qualified_display(&schema, &table)),
        None => fix_double_encoding(&app.current_db()),
    };
    // Database mode compares whole databases, so its title names the source
    // database rather than the focused table.
    let src_db = fix_double_encoding(&app.current_db());
    let target_conn = app
        .diff_picker
        .as_ref()
        .and_then(|p| p.target_conn.as_ref())
        .map(|c| c.name.clone());
    let loading = app.diff_picker.as_ref().map(|p| p.loading).unwrap_or(false);
    let comparing = app
        .diff_picker
        .as_ref()
        .map(|p| p.comparing)
        .unwrap_or(false);
    let where_input = app
        .diff_picker
        .as_ref()
        .map(|p| p.where_input.clone())
        .unwrap_or_default();
    let entries = app
        .diff_picker
        .as_ref()
        .map(|p| p.entries.clone())
        .unwrap_or_default();
    let w = if area.width > 82 {
        78
    } else {
        area.width.saturating_sub(2).max(10)
    };
    let h = if entries.is_empty() {
        4
    } else {
        (entries.len() as u16 + 3).min(area.height.saturating_sub(2).max(4))
    };
    let box_area = centered_overlay(area, w, h);
    f.render_widget(Clear, box_area);
    let data = kind == DiffKind::Data;
    let mode_key = if data {
        t("m 切结构")
    } else {
        t("d 表/库 · m 切数据")
    };
    let title = if comparing {
        let progress = app
            .data_progress
            .map(|(d, tt)| {
                if tt > 0 {
                    tf("{}/{}", &[&d, &tt])
                } else {
                    format!("{d}")
                }
            })
            .unwrap_or_else(|| "0".into());
        tf(
            " 数据对比中… · {} 块 · Esc 中止（保留已比结果） ",
            &[&progress],
        )
    } else if stage == DiffPickStage::Connections {
        if data {
            t(" 数据对比 · 选择目标连接 · Enter 进入 · Esc 返回 ").to_string()
        } else {
            t(" 结构对比 · 选择目标连接 · Enter 进入 · Esc 返回 ").to_string()
        }
    } else if let Some(tn) = target_conn {
        if data {
            tf(
                " 数据对比 · 源 {} → 连接 {} · Enter 对比 · c 换连接 · w WHERE · Esc 关 ",
                &[&src, &tn],
            )
        } else {
            tf(
                " 结构对比 · 源 {} → 连接 {} · Enter 对比 · c 换连接 · Esc 关 ",
                &[&src, &tn],
            )
        }
    } else if data {
        let mut s = tf(
            " 数据对比 · 源表 {} · 选择目标 · {} · c 换连接 · w WHERE · Enter 对比 · Esc 关 ",
            &[&src, &mode_key],
        );
        if !where_input.trim().is_empty() {
            s.push_str(&tf(" · WHERE: {} ", &[&truncate_disp(&where_input, 40)]));
        }
        s
    } else {
        match mode {
            DiffPickMode::Table => tf(
                " 结构对比 · 源表 {} · 选择目标 · {} · c 换连接 · Enter 对比 · Esc 关 ",
                &[&src, &mode_key],
            ),
            DiffPickMode::Database => tf(
                " 结构对比 · 源库 {} · 选择目标 · {} · Enter 对比 · Esc 关 ",
                &[&src_db, &mode_key],
            ),
        }
    };
    // A long diff title (source table + target + every key hint) clips on a
    // narrow terminal; fall back to the essentials (R39 titles-never-truncated).
    let title = fit_title(
        &title,
        t(" 结构/数据对比 · Enter 对比 · Esc "),
        box_area.width,
    );
    let block = Block::default()
        .borders(Borders::ALL)
        .border_set(border::ROUNDED)
        .border_style(Style::default().fg(Color::Magenta))
        .title(Span::styled(title, Style::default().fg(Color::Magenta)));
    let inner = block.inner(box_area);
    f.render_widget(block, box_area);
    if inner.width < 4 || inner.height < 1 {
        return;
    }
    if entries.is_empty() {
        let msg = if loading {
            t("加载表…").to_string()
        } else {
            t("（没有可选项）").to_string()
        };
        f.render_widget(
            Paragraph::new(Line::from(Span::styled(
                msg,
                Style::default().fg(Color::DarkGray),
            ))),
            inner,
        );
        return;
    }
    let items: Vec<ListItem> = entries
        .iter()
        .map(|e| {
            ListItem::new(Line::from(truncate_disp(
                &fix_double_encoding(e),
                inner.width as usize,
            )))
        })
        .collect();
    let list = List::new(items).highlight_style(
        Style::default()
            .bg(Color::DarkGray)
            .add_modifier(Modifier::BOLD),
    );
    if let Some(p) = app.diff_picker.as_mut() {
        f.render_stateful_widget(list, inner, &mut p.list);
    }
}

/// The two-table diff overlay (columns / indexes / generated ALTER).
fn render_diff_panel(f: &mut Frame, area: Rect, app: &mut App) {
    let Some(state) = app.diff.as_mut() else {
        return;
    };
    if area.width < 10 || area.height < 5 {
        return;
    }
    let narrow = area.width < 64;
    let badge = if state.diff.equal() {
        t("结构一致").to_string()
    } else {
        tf("{} 处差异", &[&state.diff.changed()])
    };
    let tab_label = t(state.tab.label());
    let cross = state.diff.cross;
    let alter = state.alter.clone();
    let mut title = tf(
        " 结构对比 {} → {} · {} · {} · Tab 切换 · y 摘要 · g ALTER · Esc 关 ",
        &[
            &state.diff.src.label(),
            &state.diff.tgt.label(),
            &badge,
            &tab_label,
        ],
    );
    if cross {
        title.push_str(&format!(" · {} ", t("⚠ 跨方言")));
    }
    f.render_widget(Clear, area);
    let block = Block::default()
        .borders(Borders::ALL)
        .border_set(border::ROUNDED)
        .border_style(Style::default().fg(Color::Magenta))
        .title(Span::styled(title, Style::default().fg(Color::Magenta)));
    let inner = block.inner(area);
    f.render_widget(block, area);
    if inner.width < 4 || inner.height < 2 {
        return;
    }
    // Legend line so the `+` / `-` / `~` markers read without guessing.
    let legend = if narrow {
        t("+ 新增  - 多余  ~ 差异").to_string()
    } else {
        t("+ 目标缺少（新增）   - 目标多余（删除）   ~ 属性不同").to_string()
    };
    let legend_area = Rect {
        x: inner.x,
        y: inner.y,
        width: inner.width,
        height: 1,
    };
    f.render_widget(
        Paragraph::new(Line::from(Span::styled(
            truncate_disp(&legend, inner.width as usize),
            Style::default().fg(Color::DarkGray),
        ))),
        legend_area,
    );
    let body = Rect {
        x: inner.x,
        y: inner.y + 1,
        width: inner.width,
        height: inner.height.saturating_sub(1),
    };
    if body.height == 0 {
        return;
    }
    let width = body.width as usize;
    match state.tab {
        DiffTab::Columns => {
            let items: Vec<ListItem> = state
                .diff
                .cols
                .iter()
                .map(|row| ListItem::new(diff_col_line(row, width, narrow)))
                .collect();
            let list = List::new(items).highlight_style(
                Style::default()
                    .bg(Color::DarkGray)
                    .add_modifier(Modifier::BOLD),
            );
            f.render_stateful_widget(list, body, &mut state.list);
        }
        DiffTab::Indexes => {
            if state.diff.idx.is_empty() {
                f.render_widget(
                    Paragraph::new(Line::from(Span::styled(
                        t("（没有索引信息）"),
                        Style::default().fg(Color::DarkGray),
                    ))),
                    body,
                );
                return;
            }
            let items: Vec<ListItem> = state
                .diff
                .idx
                .iter()
                .map(|row| ListItem::new(diff_index_line(row, width)))
                .collect();
            let list = List::new(items).highlight_style(
                Style::default()
                    .bg(Color::DarkGray)
                    .add_modifier(Modifier::BOLD),
            );
            f.render_stateful_widget(list, body, &mut state.list);
        }
        DiffTab::Alter => {
            let lines: Vec<Line> = alter
                .lines()
                .map(|l| {
                    let color = if l.trim_start().starts_with("--") {
                        Color::DarkGray
                    } else {
                        Color::White
                    };
                    Line::from(Span::styled(l.to_string(), Style::default().fg(color)))
                })
                .collect();
            f.render_widget(Paragraph::new(lines).scroll((state.scroll, 0)), body);
        }
    }
}

/// The two-database table-list diff overlay.
fn render_db_diff(f: &mut Frame, area: Rect, app: &mut App) {
    let Some(state) = app.db_diff.as_mut() else {
        return;
    };
    if area.width < 10 || area.height < 5 {
        return;
    }
    let only_src = state.diff.count(DbTableMark::OnlySrc);
    let only_tgt = state.diff.count(DbTableMark::OnlyTgt);
    let both = state.diff.count(DbTableMark::Both);
    let title = tf(
        " 库结构对比 {} → {} · 仅源 {} · 仅目标 {} · 共有 {} · Enter 对比同有表 · Esc 关 ",
        &[
            &state.diff.src_label,
            &state.diff.tgt_label,
            &only_src,
            &only_tgt,
            &both,
        ],
    );
    f.render_widget(Clear, area);
    let block = Block::default()
        .borders(Borders::ALL)
        .border_set(border::ROUNDED)
        .border_style(Style::default().fg(Color::Magenta))
        .title(Span::styled(title, Style::default().fg(Color::Magenta)));
    let inner = block.inner(area);
    f.render_widget(block, area);
    if inner.width < 4 || inner.height < 1 {
        return;
    }
    let width = inner.width as usize;
    let items: Vec<ListItem> = state
        .diff
        .entries
        .iter()
        .map(|e| {
            let (sign, color) = match e.mark {
                DbTableMark::OnlySrc => ("+", Color::Green),
                DbTableMark::OnlyTgt => ("-", Color::Red),
                DbTableMark::Both => ("=", Color::Gray),
            };
            Line::from(vec![
                Span::styled(
                    format!(" {sign} "),
                    Style::default().fg(color).add_modifier(Modifier::BOLD),
                ),
                Span::styled(
                    truncate_disp(
                        &fix_double_encoding(&e.table),
                        width.saturating_sub(3).max(4),
                    ),
                    Style::default().fg(if e.mark == DbTableMark::Both {
                        Color::White
                    } else {
                        color
                    }),
                ),
            ])
            .into()
        })
        .collect();
    let list = List::new(items).highlight_style(
        Style::default()
            .bg(Color::DarkGray)
            .add_modifier(Modifier::BOLD),
    );
    f.render_stateful_widget(list, inner, &mut state.list);
}

/// One list line for an only-source / only-target data row: the marker, the
/// primary key, then as many other column values as fit.
fn data_only_line(row: &DataDiffRow, align: &DataAlign, width: usize) -> Line<'static> {
    let color = row.mark.color();
    let mut spans = vec![
        Span::styled(
            format!(" {} ", row.mark.sign()),
            Style::default().fg(color).add_modifier(Modifier::BOLD),
        ),
        Span::styled(
            row.key.clone(),
            Style::default()
                .fg(Color::White)
                .add_modifier(Modifier::BOLD),
        ),
    ];
    let mut used = row.key.chars().count() + 3;
    for (i, col) in align.cols.iter().enumerate().skip(align.pk_len) {
        let Some(v) = row.vals.get(i) else {
            continue;
        };
        let (text, _) = value_display(v);
        let piece = format!(" · {}={}", col.name, text);
        if used + piece.chars().count() > width.saturating_sub(2) {
            break;
        }
        used += piece.chars().count();
        spans.push(Span::styled(piece, Style::default().fg(Color::Gray)));
    }
    Line::from(spans)
}

/// One list line for a `≠` row: the key and the names of the differing columns.
fn data_diff_row_line(row: &DataDiffRow, width: usize) -> Line<'static> {
    let head = format!(" ≠ {} ", row.key);
    let mut rest = row
        .cells
        .iter()
        .map(|c| c.col.clone())
        .collect::<Vec<_>>()
        .join(", ");
    if row.cells.iter().any(|c| c.unknown_type) {
        rest.push_str(" ?");
    }
    let avail = width.saturating_sub(head.chars().count() + 2).max(4);
    Line::from(vec![
        Span::styled(
            head,
            Style::default()
                .fg(Color::Yellow)
                .add_modifier(Modifier::BOLD),
        ),
        Span::styled(
            truncate_disp(&rest, avail),
            Style::default().fg(Color::Gray),
        ),
    ])
}

/// The two-table data-diff overlay (summary / only-src / only-tgt / diff / sync).
fn render_data_diff(f: &mut Frame, area: Rect, app: &mut App) {
    let Some(state) = app.data_diff.as_mut() else {
        return;
    };
    if area.width < 10 || area.height < 5 {
        return;
    }
    let narrow = area.width < 64;
    let cmp = &state.result;
    let badge = if cmp.equal() {
        t("数据一致").to_string()
    } else {
        tf("{} 处差异", &[&cmp.changed()])
    };
    let tab_label = t(state.tab.label());
    let mut title = tf(
        " 数据对比 {} → {} · {} · {} · Tab 切换 · y 摘要 · g 同步 SQL · Esc 关 ",
        &[&cmp.src_label, &cmp.tgt_label, &badge, &tab_label],
    );
    if cmp.cross() {
        title.push_str(&format!(" · {} ", t("⚠ 跨方言")));
    }
    if cmp.truncated {
        title.push_str(&format!(" · {} ", t("⚠ 已截断")));
    }
    if cmp.cancelled {
        title.push_str(&format!(" · {} ", t("已中止")));
    }
    f.render_widget(Clear, area);
    let block = Block::default()
        .borders(Borders::ALL)
        .border_set(border::ROUNDED)
        .border_style(Style::default().fg(Color::Magenta))
        .title(Span::styled(title, Style::default().fg(Color::Magenta)));
    let inner = block.inner(area);
    f.render_widget(block, area);
    if inner.width < 4 || inner.height < 2 {
        return;
    }
    let count = |v: Option<u64>| v.map(|n| n.to_string()).unwrap_or_else(|| "?".into());
    let summary = format!(
        "{} {} · {} {} · {} {} · {} {} · {} {}",
        t("源"),
        count(cmp.src_count),
        t("目标"),
        count(cmp.tgt_count),
        t("仅源"),
        cmp.only_src,
        t("仅目标"),
        cmp.only_tgt,
        t("差异"),
        cmp.differing,
    );
    // Header line: counts + filter.
    let header = if cmp.filter.trim().is_empty() {
        summary
    } else {
        format!(
            "{} · {}: {}",
            summary,
            t("过滤"),
            truncate_disp(&one_line(&cmp.filter), 40)
        )
    };
    let header_area = Rect {
        x: inner.x,
        y: inner.y,
        width: inner.width,
        height: 1,
    };
    f.render_widget(
        Paragraph::new(Line::from(Span::styled(
            truncate_disp(&header, inner.width as usize),
            Style::default().fg(Color::Gray),
        ))),
        header_area,
    );
    let body = Rect {
        x: inner.x,
        y: inner.y + 1,
        width: inner.width,
        height: inner.height.saturating_sub(1),
    };
    if body.height == 0 {
        return;
    }
    let width = body.width as usize;
    match state.tab {
        DataTab::Summary => {
            let pk = cmp
                .align
                .pk()
                .iter()
                .map(|c| c.name.clone())
                .collect::<Vec<_>>()
                .join(", ");
            let cols = cmp
                .align
                .cols
                .iter()
                .map(|c| c.name.clone())
                .collect::<Vec<_>>()
                .join(", ");
            let mut lines = vec![
                Line::from(Span::styled(
                    t("按主键归一对齐，分块流式拉取（每块 1000 行）。"),
                    Style::default().fg(Color::DarkGray),
                )),
                Line::from(Span::raw(format!("{}: {}", t("主键"), pk))),
                Line::from(Span::raw(format!(
                    "{}: {}",
                    t("对比列"),
                    truncate_disp(&cols, width.saturating_sub(8))
                ))),
            ];
            if cmp.equal() {
                lines.push(Line::from(Span::styled(
                    t("数据一致，无差异。"),
                    Style::default().fg(Color::Green),
                )));
            } else {
                lines.push(Line::from(Span::styled(
                    t("Tab 切换到 仅源 / 仅目标 / 差异 查看明细；差异行按 Enter 展开列级对照。"),
                    Style::default().fg(Color::DarkGray),
                )));
            }
            f.render_widget(Paragraph::new(lines).wrap(Wrap { trim: true }), body);
        }
        DataTab::OnlySrc | DataTab::OnlyTgt | DataTab::Diff => {
            let legend = if narrow {
                t("< 仅源  > 仅目标  ≠ 差异").to_string()
            } else {
                t("< 仅源有   > 仅目标有   ≠ 两边都有但内容不同（Enter 展开列级对照）").to_string()
            };
            let legend_area = Rect {
                x: body.x,
                y: body.y,
                width: body.width,
                height: 1,
            };
            f.render_widget(
                Paragraph::new(Line::from(Span::styled(
                    truncate_disp(&legend, width),
                    Style::default().fg(Color::DarkGray),
                ))),
                legend_area,
            );
            let list_area = Rect {
                x: body.x,
                y: body.y + 1,
                width: body.width,
                height: body.height.saturating_sub(1),
            };
            if list_area.height == 0 {
                return;
            }
            let items: Vec<ListItem> = match state.tab {
                DataTab::Diff => cmp
                    .rows
                    .iter()
                    .filter(|r| r.mark == RowMark::Diff)
                    .map(|r| ListItem::new(data_diff_row_line(r, width)))
                    .collect(),
                _ => {
                    let mark = if state.tab == DataTab::OnlySrc {
                        RowMark::OnlySrc
                    } else {
                        RowMark::OnlyTgt
                    };
                    cmp.rows
                        .iter()
                        .filter(|r| r.mark == mark)
                        .map(|r| ListItem::new(data_only_line(r, &cmp.align, width)))
                        .collect()
                }
            };
            if items.is_empty() {
                f.render_widget(
                    Paragraph::new(Line::from(Span::styled(
                        t("（本类没有行）"),
                        Style::default().fg(Color::DarkGray),
                    ))),
                    list_area,
                );
                return;
            }
            let list = List::new(items).highlight_style(
                Style::default()
                    .bg(Color::DarkGray)
                    .add_modifier(Modifier::BOLD),
            );
            f.render_stateful_widget(list, list_area, &mut state.list);
        }
        DataTab::Sync => {
            let sql = state.sync_sql.clone();
            let lines: Vec<Line> = sql
                .lines()
                .map(|l| {
                    let color = if l.trim_start().starts_with("--") {
                        Color::DarkGray
                    } else {
                        Color::White
                    };
                    Line::from(Span::styled(l.to_string(), Style::default().fg(color)))
                })
                .collect();
            f.render_widget(Paragraph::new(lines).scroll((state.scroll, 0)), body);
        }
    }
}

/// The optional data-compare `WHERE` input.
fn render_data_where(f: &mut Frame, area: Rect, app: &mut App) {
    let w = overlay_width(area.width, 74, 24);
    let h = 7.min(area.height);
    let box_area = centered_overlay(area, w, h);
    f.render_widget(Clear, box_area);
    let block = Block::default()
        .borders(Borders::ALL)
        .title(fit_title(
            t(" 数据对比 WHERE（两边同时生效）· Enter 开始 · Esc 取消 "),
            t(" 数据对比 WHERE · Enter 开始 "),
            box_area.width,
        ))
        .border_set(border::ROUNDED)
        .border_style(Style::default().fg(Color::Yellow));
    let inner = block.inner(box_area);
    f.render_widget(block, box_area);
    let hint_h = 2u16.min(inner.height.saturating_sub(1));
    let ta_h = inner.height.saturating_sub(hint_h).max(1);
    let ta_area = Rect {
        x: inner.x,
        y: inner.y,
        width: inner.width,
        height: ta_h,
    };
    let hint_area = Rect {
        x: inner.x,
        y: inner.y + ta_h,
        width: inner.width,
        height: hint_h,
    };
    if let Some(ta) = app.data_where.as_mut() {
        ta.set_block(Block::default());
        f.render_widget(&*ta, ta_area);
    }
    if hint_h > 0 {
        let hints = vec![
            Line::from(Span::styled(
                t("例: created_at > '2026-01-01' AND status = 'active'"),
                Style::default().fg(Color::DarkGray),
            )),
            Line::from(Span::styled(
                t("两边使用相同条件；列名按各自方言书写 · 留空 = 无过滤"),
                Style::default().fg(Color::DarkGray),
            )),
        ];
        f.render_widget(Paragraph::new(hints), hint_area);
    }
}

/// The `Alt-T` transfer wizard overlay (three steps + the red overwrite layer).
fn render_transfer_wizard(f: &mut Frame, area: Rect, app: &mut App) {
    if app.transfer.as_ref().is_some_and(|w| w.submitted) {
        render_transfer_running(f, area, app);
        return;
    }
    let step = match app.transfer.as_ref().map(|w| w.step) {
        Some(s) => s,
        None => return,
    };
    if area.width < 12 || area.height < 5 {
        return;
    }
    let w = if area.width > 88 {
        84
    } else {
        area.width.saturating_sub(2).max(10)
    };
    match step {
        TransferStep::Connection => {
            let (src, entries) = {
                let w = app.transfer.as_ref().unwrap();
                (
                    fix_double_encoding(&qualified_display(&w.src_schema, &w.src_table)),
                    w.conns
                        .iter()
                        .map(|c| format!("{}  ({})", c.name, c.db_type.as_str()))
                        .collect::<Vec<_>>(),
                )
            };
            let h = (entries.len() as u16 + 3).min(area.height.saturating_sub(2).max(4));
            let box_area = centered_overlay(area, w, h);
            f.render_widget(Clear, box_area);
            let block = Block::default()
                .borders(Borders::ALL)
                .border_set(border::ROUNDED)
                .border_style(Style::default().fg(Color::Cyan))
                .title(fit_title(
                    &tf(
                        " 数据搬运 ① 目标连接 · 源 {} · Enter 下一步 · Esc 取消 ",
                        &[&src],
                    ),
                    t(" 数据搬运 ① · Enter 下一步 "),
                    box_area.width,
                ));
            let inner = block.inner(box_area);
            f.render_widget(block, box_area);
            let items: Vec<ListItem> = entries.iter().map(|e| ListItem::new(e.clone())).collect();
            let list = List::new(items)
                .highlight_style(
                    Style::default()
                        .fg(Color::Black)
                        .bg(Color::Cyan)
                        .add_modifier(Modifier::BOLD),
                )
                .highlight_symbol("▸ ");
            let list_state = &mut app.transfer.as_mut().unwrap().conn_list;
            f.render_stateful_widget(list, inner, list_state);
        }
        TransferStep::Name => {
            let (tgt, lines, focus_label, live) = {
                let w = app.transfer.as_ref().unwrap();
                let tgt = format!(
                    "{} ({})",
                    w.target_conn.name,
                    w.target_conn.db_type.as_str()
                );
                let labels = [t("数据库"), t("模式/Schema"), t("目标表名")];
                let live = w.name_input.lines().join("\n");
                let mut lines = Vec::new();
                for (i, label) in labels.iter().enumerate() {
                    let val = if i == w.name_focus.index() {
                        live.clone()
                    } else {
                        w.name_values[i].clone()
                    };
                    let mark = if i == w.name_focus.index() {
                        "▸"
                    } else {
                        " "
                    };
                    lines.push(format!("{mark} {label:<10} {val}"));
                }
                (tgt, lines, labels[w.name_focus.index()], live)
            };
            let _ = live;
            let h = 9.min(area.height.saturating_sub(2).max(5));
            let box_area = centered_overlay(area, w, h);
            f.render_widget(Clear, box_area);
            let block = Block::default()
                .borders(Borders::ALL)
                .border_set(border::ROUNDED)
                .border_style(Style::default().fg(Color::Cyan))
                .title(fit_title(
                    &tf(
                        " 数据搬运 ② 目标库/表 · {} · Tab 切换 · Enter 下一步 · Esc 返回 ",
                        &[&tgt],
                    ),
                    t(" 数据搬运 ② · Tab/Enter "),
                    box_area.width,
                ));
            let inner = block.inner(box_area);
            f.render_widget(block, box_area);
            let err = app.transfer.as_ref().and_then(|w| w.error.clone());
            let mut text_lines: Vec<Line> = lines
                .iter()
                .map(|l| Line::from(Span::styled(l.clone(), Style::default().fg(Color::Gray))))
                .collect();
            text_lines.push(Line::from(""));
            text_lines.push(Line::from(Span::styled(
                tf("编辑字段: {}（直接输入，Tab 切换）", &[&focus_label]),
                Style::default().fg(Color::DarkGray),
            )));
            if let Some(e) = err {
                text_lines.push(Line::from(Span::styled(e, Style::default().fg(Color::Red))));
            }
            let list_h = text_lines.len() as u16;
            let para = Paragraph::new(text_lines);
            f.render_widget(
                para,
                Rect {
                    x: inner.x,
                    y: inner.y,
                    width: inner.width,
                    height: list_h.min(inner.height),
                },
            );
            // The live one-line editor for the focused field.
            let input_y = inner.y + list_h.min(inner.height);
            if input_y < inner.y + inner.height {
                let input_area = Rect {
                    x: inner.x,
                    y: input_y,
                    width: inner.width,
                    height: 1,
                };
                if let Some(w) = app.transfer.as_mut() {
                    w.name_input.set_block(Block::default());
                    f.render_widget(&w.name_input, input_area);
                }
            }
        }
        TransferStep::Options => {
            let (rows, cursor, mode, where_v, large) = {
                let w = app.transfer.as_ref().unwrap();
                (
                    transfer_option_rows(w),
                    w.opt_list.selected().unwrap_or(0),
                    w.mode,
                    w.where_input.clone(),
                    w.large_warn,
                )
            };
            let _ = mode;
            let _ = where_v;
            let h = (rows.len() as u16 + 4).min(area.height.saturating_sub(2).max(5));
            let box_area = centered_overlay(area, w, h);
            f.render_widget(Clear, box_area);
            let block = Block::default()
                .borders(Borders::ALL)
                .border_set(border::ROUNDED)
                .border_style(Style::default().fg(Color::Cyan))
                .title(fit_title(
                    t(" 数据搬运 ③ 模式与选项 · ↑↓ 选择 · Enter 切换 · Enter 开搬 · Esc 取消 "),
                    t(" 数据搬运 ③ · Enter 开搬 "),
                    box_area.width,
                ));
            let inner = block.inner(box_area);
            f.render_widget(block, box_area);
            let items: Vec<ListItem> = rows
                .iter()
                .enumerate()
                .map(|(i, (label, value))| {
                    if i == rows.len() - 1 {
                        ListItem::new(Line::from(Span::styled(
                            format!("▶ {label}"),
                            Style::default()
                                .fg(Color::Green)
                                .add_modifier(Modifier::BOLD),
                        )))
                    } else {
                        ListItem::new(format!("{label:<12} {value}"))
                    }
                })
                .collect();
            let list = List::new(items)
                .highlight_style(
                    Style::default()
                        .fg(Color::Black)
                        .bg(Color::Cyan)
                        .add_modifier(Modifier::BOLD),
                )
                .highlight_symbol("▸ ");
            let mut state = ListState::default();
            state.select(Some(cursor));
            let list_h = (rows.len() as u16).min(inner.height.saturating_sub(2));
            f.render_stateful_widget(
                list,
                Rect {
                    x: inner.x,
                    y: inner.y,
                    width: inner.width,
                    height: list_h,
                },
                &mut state,
            );
            let note_y = inner.y + list_h;
            if note_y < inner.y + inner.height {
                let note = if let Some(n) = large {
                    Line::from(Span::styled(
                        tf("⚠ 预估 {} 行，再按 Enter 确认开始", &[&n]),
                        Style::default().fg(Color::Yellow),
                    ))
                } else {
                    Line::from(Span::styled(
                        t("m 模式 · o 覆盖 · s 出错处理 · w/l WHERE/LIMIT · i 索引 · a 自增"),
                        Style::default().fg(Color::DarkGray),
                    ))
                };
                f.render_widget(
                    Paragraph::new(note),
                    Rect {
                        x: inner.x,
                        y: note_y,
                        width: inner.width,
                        height: 1,
                    },
                );
            }
        }
        TransferStep::Confirm => {
            let tgt = {
                let w = app.transfer.as_ref().unwrap();
                format!(
                    "{} · {} · {}",
                    w.target_conn.name,
                    w.name_values[0],
                    qualified_display(&w.name_values[1], &w.name_values[2])
                )
            };
            let h = 8.min(area.height.saturating_sub(2).max(5));
            let box_area = centered_overlay(area, w, h);
            f.render_widget(Clear, box_area);
            let block = Block::default()
                .borders(Borders::ALL)
                .border_set(border::ROUNDED)
                .border_style(Style::default().fg(Color::Red).add_modifier(Modifier::BOLD))
                .title(t(" ⚠ 覆盖确认 · 将先 DROP 目标表 "));
            let inner = block.inner(box_area);
            f.render_widget(block, box_area);
            let lines = vec![
                Line::from(Span::styled(
                    tf("目标表: {}", &[&tgt]),
                    Style::default().fg(Color::White),
                )),
                Line::from(Span::styled(
                    t("DROP TABLE 会永久删除目标表的全部数据，且无法恢复。"),
                    Style::default().fg(Color::Red),
                )),
                Line::from(""),
                Line::from(Span::styled(
                    t("Enter 确认覆盖并开始搬运 · Esc 返回（保持报错停下）"),
                    Style::default().fg(Color::Yellow),
                )),
            ];
            f.render_widget(Paragraph::new(lines).wrap(Wrap { trim: false }), inner);
        }
    }
}

/// The read-only progress overlay shown while a transfer runs.
fn render_transfer_running(f: &mut Frame, area: Rect, app: &mut App) {
    let Some(w) = app.transfer.as_ref() else {
        return;
    };
    if area.width < 12 || area.height < 5 {
        return;
    }
    let src = fix_double_encoding(&qualified_display(&w.src_schema, &w.src_table));
    let table = w.name_values[2].clone();
    let box_w = if area.width > 76 {
        72
    } else {
        area.width.saturating_sub(2).max(10)
    };
    let h = 7.min(area.height.saturating_sub(2).max(4));
    let box_area = centered_overlay(area, box_w, h);
    f.render_widget(Clear, box_area);
    let block = Block::default()
        .borders(Borders::ALL)
        .border_set(border::ROUNDED)
        .border_style(Style::default().fg(Color::Cyan))
        .title(fit_title(
            t(" 数据搬运中… · Esc 中止（已提交批次保留） "),
            t(" 数据搬运中… · Esc 中止 "),
            box_area.width,
        ));
    let inner = block.inner(box_area);
    f.render_widget(block, box_area);
    let (rows, chunks, elapsed, total) = app.transfer_progress.unwrap_or((0, 0, 0, None));
    let rate = (rows as u128 * 1000)
        .checked_div(elapsed)
        .unwrap_or(rows as u128) as u64;
    let mut lines = vec![
        Line::from(Span::styled(
            tf("{} → {}", &[&src, &fix_double_encoding(&table)]),
            Style::default().fg(Color::White),
        )),
        Line::from(""),
        Line::from(Span::styled(
            tf(
                "已搬 {} 行 / 已完成 {} 块 ({} 行/秒)",
                &[&rows, &chunks, &rate],
            ),
            Style::default().fg(Color::Green),
        )),
    ];
    if let Some(t) = total.filter(|t| *t > 0) {
        lines.push(Line::from(Span::styled(
            tf("源预估 {} 行", &[&t]),
            Style::default().fg(Color::DarkGray),
        )));
    }
    lines.push(Line::from(""));
    lines.push(Line::from(Span::styled(
        t("Esc 中止并保留已提交批次；完成前请勿关闭终端"),
        Style::default().fg(Color::DarkGray),
    )));
    f.render_widget(Paragraph::new(lines).wrap(Wrap { trim: false }), inner);
}

/// The `WHERE` / `LIMIT` input for the transfer wizard's options step.
fn render_transfer_prompt(f: &mut Frame, area: Rect, app: &mut App) {
    let Some(w) = app.transfer.as_ref() else {
        return;
    };
    let Some(p) = w.prompt.as_ref() else {
        return;
    };
    let field = p.field;
    let label = match field {
        TransferField::Where => t("数据搬运 WHERE（只搬子集）"),
        TransferField::Limit => t("数据搬运 LIMIT 上限"),
    };
    let box_w = if area.width.saturating_sub(4) < 24 {
        area.width
    } else {
        (area.width - 4).min(74)
    };
    let h = 7.min(area.height);
    let box_area = centered_overlay(area, box_w, h);
    f.render_widget(Clear, box_area);
    let block = Block::default()
        .borders(Borders::ALL)
        .border_set(border::ROUNDED)
        .border_style(Style::default().fg(Color::Yellow))
        .title(tf(" {} · Enter 确定 · Esc 取消 ", &[&label]));
    let inner = block.inner(box_area);
    f.render_widget(block, box_area);
    let hint_h = 2u16.min(inner.height.saturating_sub(1));
    let ta_h = inner.height.saturating_sub(hint_h).max(1);
    let ta_area = Rect {
        x: inner.x,
        y: inner.y,
        width: inner.width,
        height: ta_h,
    };
    let hint_area = Rect {
        x: inner.x,
        y: inner.y + ta_h,
        width: inner.width,
        height: hint_h,
    };
    if let Some(w) = app.transfer.as_mut() {
        if let Some(p) = w.prompt.as_mut() {
            p.input.set_block(Block::default());
            f.render_widget(&p.input, ta_area);
        }
    }
    if hint_h > 0 {
        let hint = match field {
            TransferField::Where => t("例: id > 100 AND status = 'ok'（留空 = 全表）"),
            TransferField::Limit => t("例: 5000（留空 = 不限；顶层上限）"),
        };
        f.render_widget(
            Paragraph::new(Line::from(Span::styled(
                hint,
                Style::default().fg(Color::DarkGray),
            ))),
            hint_area,
        );
    }
}

/// The transfer completion summary (`Alt-T`).
fn render_transfer_report(f: &mut Frame, area: Rect, app: &mut App) {
    let Some(rep) = app.transfer_report.as_ref() else {
        return;
    };
    if area.width < 12 || area.height < 5 {
        return;
    }
    let box_w = if area.width > 88 {
        84
    } else {
        area.width.saturating_sub(2).max(10)
    };
    let h = 16.min(area.height.saturating_sub(2).max(5));
    let box_area = centered_overlay(area, box_w, h);
    f.render_widget(Clear, box_area);
    let color = if rep.ok() {
        Color::Green
    } else if rep.cancelled {
        Color::Yellow
    } else {
        Color::Red
    };
    let block = Block::default()
        .borders(Borders::ALL)
        .border_set(border::ROUNDED)
        .border_style(Style::default().fg(color))
        .title(fit_title(
            t(" 数据搬运汇总 · g 复制摘要 · b 浏览目标表 · Esc 关闭 "),
            t(" 搬运汇总 · g 摘要 · b 浏览 "),
            box_area.width,
        ));
    let inner = block.inner(box_area);
    f.render_widget(block, box_area);

    let mut lines: Vec<Line> = Vec::new();
    let kv = |k: &str, v: String| {
        Line::from(vec![
            Span::styled(format!("{k}: "), Style::default().fg(Color::DarkGray)),
            Span::raw(v),
        ])
    };
    lines.push(kv(
        t("源"),
        format!("{} ({})", rep.src_label, rep.src_db_type.as_str()),
    ));
    let conflict = if rep.mode == TransferMode::Append {
        String::new()
    } else {
        format!(" · {}", t(rep.conflict.label()))
    };
    lines.push(kv(
        t("目标"),
        format!(
            "{} ({}) · {}{} · {}",
            rep.tgt_label,
            rep.tgt_db_type.as_str(),
            t(rep.mode.label()),
            conflict,
            t(rep.on_error.label())
        ),
    ));
    let src_rows = rep.src_rows;
    lines.push(kv(
        t("已搬运"),
        tf(
            "{} 行 · 跳过 {} 行 · 源读取 {} 行 · {} 块",
            &[&rep.moved, &rep.skipped.len(), &src_rows, &rep.chunks_done],
        ),
    ));
    lines.push(kv(
        t("耗时/速率"),
        format!("{}ms · {} {}", rep.elapsed_ms, rep.rate(), t("行/秒")),
    ));
    lines.push(kv(
        t("源预估"),
        rep.estimated
            .map(|n| n.to_string())
            .unwrap_or_else(|| "?".to_string()),
    ));
    if rep.created {
        lines.push(kv(t("建表"), t("已在目标创建").to_string()));
    }
    if let Some(bp) = &rep.breakpoint {
        lines.push(kv(t("断点主键"), bp.clone()));
    }
    if rep.cancelled {
        lines.push(Line::from(Span::styled(
            t("⚠ 已中止（已提交批次保留，可按断点续搬）"),
            Style::default().fg(Color::Yellow),
        )));
    }
    if let Some((row, err)) = &rep.aborted {
        lines.push(Line::from(Span::styled(
            tf("✗ 中止于源行 {}: {}", &[&row, &err]),
            Style::default().fg(Color::Red),
        )));
    }
    for (row, err) in rep.skipped.iter().take(3) {
        lines.push(Line::from(Span::styled(
            tf("跳过源行 {}: {}", &[&row, &err]),
            Style::default().fg(Color::Yellow),
        )));
    }
    for warn in rep.warnings.iter().take(2) {
        lines.push(Line::from(Span::styled(
            tf("⚠ {}", &[&warn]),
            Style::default().fg(Color::Yellow),
        )));
    }
    f.render_widget(Paragraph::new(lines).wrap(Wrap { trim: false }), inner);
}

/// The `Alt-L` file-path input, drawn as a one-line box at the bottom.
fn render_file_load_prompt(f: &mut Frame, area: Rect, app: &mut App) {
    if area.height < 3 || area.width < 12 {
        return;
    }
    let w = area.width.saturating_sub(4).max(20).min(area.width);
    let h = 3.min(area.height);
    let x = area.x + (area.width.saturating_sub(w)) / 2;
    let y = area.y + area.height.saturating_sub(h + 1);
    let box_area = Rect {
        x,
        y,
        width: w,
        height: h,
    };
    f.render_widget(Clear, box_area);
    let block = Block::default()
        .borders(Borders::ALL)
        .title(fit_title(
            &tf(
                " 加载 SQL 文件 · {} · Enter 预览 · Esc 取消 ",
                &[&(app.selected_name())],
            ),
            t(" 加载 SQL 文件 · Enter 预览 "),
            box_area.width,
        ))
        .border_set(border::ROUNDED)
        .border_style(Style::default().fg(Color::Cyan));
    let inner = block.inner(box_area);
    f.render_widget(block, box_area);
    if let Some(ta) = app.file_load_prompt.as_mut() {
        ta.set_block(Block::default());
        f.render_widget(&*ta, inner);
    }
}

/// The `Alt-L` confirmation layer: file size, statement count, target connection
/// and a wrapped preview of the script, with any destructive statements called
/// out in red before Enter runs it.
fn render_file_load_plan(f: &mut Frame, area: Rect, app: &mut App) {
    let Some(plan) = app.file_load_plan.as_ref() else {
        return;
    };
    if area.width < 14 || area.height < 5 {
        return;
    }
    let w = if area.width < 32 {
        area.width
    } else {
        area.width.saturating_sub(4).min(84)
    };
    let inner_w = w.saturating_sub(4).max(1) as usize;
    let sql_lines = wrap_sql_lines(&plan.sql, inner_w);
    let max_h = area.height.saturating_sub(2) as usize;
    let h = (sql_lines.len() + 8).min(max_h).max(5) as u16;
    let box_area = centered_overlay(area, w, h);
    f.render_widget(Clear, box_area);

    let target = if plan.db.trim().is_empty() {
        plan.connection.clone()
    } else {
        format!("{}.{}", plan.connection, fix_double_encoding(&plan.db))
    };
    let label = Style::default().fg(Color::DarkGray);
    let value = Style::default().fg(Color::White);
    let mut lines: Vec<Line> = Vec::new();
    lines.push(Line::from(vec![
        Span::styled(t("文件 "), label),
        Span::styled(
            plan.path.display().to_string(),
            value.add_modifier(Modifier::BOLD),
        ),
    ]));
    lines.push(Line::from(vec![
        Span::styled(t("大小 "), label),
        Span::styled(human_size(plan.bytes), value),
        Span::styled(t(" · 语句 "), label),
        Span::styled(plan.statements.to_string(), value),
        Span::styled(t(" · 目标 "), label),
        Span::styled(target, value),
    ]));
    if let Some(w) = &plan.warning {
        lines.push(Line::from(Span::styled(
            format!("⚠ {w}"),
            Style::default().fg(Color::Yellow),
        )));
    }
    for d in &plan.danger {
        lines.push(Line::from(Span::styled(
            format!("⚠ {d}"),
            Style::default().fg(Color::Red).add_modifier(Modifier::BOLD),
        )));
    }
    lines.push(Line::from(""));
    let room = (box_area.height as usize).saturating_sub(lines.len() + 2);
    for l in sql_lines.iter().take(room) {
        lines.push(Line::from(Span::styled(
            l.clone(),
            Style::default().fg(Color::White),
        )));
    }
    if sql_lines.len() > room {
        lines.push(Line::from(Span::styled(
            tf("…（预览截断，共 {} 行）", &[&(sql_lines.len())]),
            Style::default().fg(Color::DarkGray),
        )));
    }
    lines.push(Line::from(Span::styled(
        t("Enter 执行 · e 转编辑器 · Esc 取消"),
        Style::default().fg(Color::Yellow),
    )));
    let border = if plan.danger.is_empty() {
        Color::Cyan
    } else {
        Color::Red
    };
    let block = Block::default()
        .borders(Borders::ALL)
        .border_set(border::ROUNDED)
        .border_style(Style::default().fg(border))
        .title(Span::styled(
            t(" 执行 SQL 文件 "),
            Style::default().fg(border).add_modifier(Modifier::BOLD),
        ));
    f.render_widget(Paragraph::new(lines).block(block), box_area);
}

