        assert_eq!(map_driver_to_db_type("mariadb"), Some("mysql"));
        assert_eq!(map_driver_to_db_type("PostgreSQL"), Some("postgres"));
        assert_eq!(map_driver_to_db_type("MSSQL"), Some("sqlserver"));
